// ═══ supabase/claude-src/jobs.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · the job list
//
//  Every job the function can run, by name. A request names its job and this
//  fixed list answers; nothing a request sends can add a job or change one.
//  A new job is a new job-<name>.ts file and one line here.
// ─────────────────────────────────────────────────────────────────────────────

const JOB_LIST: readonly JobDefinition[] = [
  ITEM_FILL_JOB, RECIPE_FROM_TEXT_JOB, RECIPE_FROM_LINK_JOB, RECIPE_MACROS_JOB, QUICK_GUESS_JOB, QUICK_GUESS_OPTIONS_JOB,
  // The AI features the owner picked (22.11.2026): photos, Dev Requests, Work, Shop, Wishes.
  QUICK_GUESS_PHOTO_JOB, RECEIPT_READ_JOB, DEV_REQUEST_DRAFT_JOB, ERROR_EXPLAIN_JOB, WORK_WEEK_JOB, AD_IMPROVE_JOB, PLACE_IDEAS_JOB, SHOP_TIDY_JOB,
  COACH_ASSESSMENT_JOB, KOBO_ASK_JOB, PHONE_ASK_JOB, WEEKLY_REPORT_JOB, SUGGEST_WEEKLY_JOB, TEST_BENCH_JOB, DIAGNOSE_JOB, CHAT_JOB,
]

// A Map, not a plain object: a name like "constructor" or "__proto__" finds nothing in it.
const JOBS_BY_NAME: ReadonlyMap<string, JobDefinition> = new Map(JOB_LIST.map(job => [job.name, job]))

function findJob(name: unknown): JobDefinition | null {
  return typeof name === 'string' ? JOBS_BY_NAME.get(name) ?? null : null
}

// ═══ supabase/claude-src/run.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · one run
//
//  One request for one job, from the name in the request to the answer the app
//  gets. The order of the steps below is the design: every wall comes before
//  the model is called, and whatever happens is written to the ledger.
//
//  This part knows no provider. It is handed one (types.ts → Provider) and
//  only ever sees our own request and answer shapes.
// ─────────────────────────────────────────────────────────────────────────────

/** A notification: fixed words built by code, and where a tap opens (a hash route inside the app). */
interface PushMessage {
  title: string
  body: string
  url: string
}

/** Everything a run needs from outside, handed in by main.ts (or by a test). */
interface RunContext {
  /** The account the session belongs to, as main.ts verified it. Never a value from the request. */
  userId: string
  caller: Caller
  /**
   * Who reads the owner's settings and the ledger's counts. `owner` (the app): `userDb` carries the owner's own
   * token, so row level security decides what it reads and `ai_gate` answers. `server` (a device run, which has no
   * token): `userDb` is the service-role client, every read of it is scoped to `userId` in the query itself.
   */
  readAs: 'owner' | 'server'
  /** The database client the settings and the ledger counts are read with (see `readAs`). */
  userDb: Db
  /** The service-role client: the only writer of the ledger. */
  adminDb: Db
  /** The model provider, or null while no API key is configured. */
  provider: Provider | null
  providerName: string
  /** The network and the name lookup for a job that reads an outside page (page-fetch.ts). */
  page: PageEnv
  /** The secrets this function holds, to keep out of every message. */
  secrets: readonly (string | null | undefined)[]
  now: () => Date
  newId: () => string
  /** A longer limit for this run's request than the provider's 30 s: only Diagnose sets it. */
  timeoutMs?: number
  /**
   * Sends one notification to the owner's phone (main.ts: push-send, with a secret this function holds), or null when
   * there is no way to. The weekly report is the only caller; the text is built by code, never from the model.
   */
  push?: ((message: PushMessage) => Promise<boolean>) | null
  /** One line for the server log. It never gets a secret or any of the owner's text. */
  report: (line: string) => void
}

// What the ledger shows for a request that named no job this function has.
const RUN_UNKNOWN_JOB = 'unknown'
const RUN_NO_MODEL = 'none'
// The provider column of a row for work code did alone (no model asked).
const RUN_PAGE_PROVIDER = 'page'
const RUN_ERROR_MAX = 500
// A call that failed in one of these ways may still have been billed (the request may have reached the model), so
// its row keeps the reserved worst-case cost. A refusal at the door (a bad key, a bad request, a spend limit, a 429)
// never started a generation.
const RUN_MAY_BE_BILLED: readonly ModelFailure['kind'][] = ['network', 'timeout', 'overloaded', 'provider_fault', 'unknown']
const RUN_NO_TOKENS: TokenUsage = {
  inputTokens: 0, cacheReadTokens: 0, cacheWrite5mTokens: 0, cacheWrite1hTokens: 0, outputTokens: 0, thinkingTokens: 0,
}

/** A ledger row for this run, with every column at "nothing happened yet". */
function newRow(ctx: RunContext, job: JobDefinition | null | undefined): CallRow {
  return {
    id: ctx.newId(), user_id: ctx.userId, run_id: ctx.newId(), step: 1,
    job: job?.name ?? RUN_UNKNOWN_JOB, caller: ctx.caller, mode: 'live', provider: ctx.providerName,
    model: job?.defaults.model ?? RUN_NO_MODEL, served_model: null, effort: null,
    outcome: 'error', stop_reason: null, error: null, request_id: null,
    input_tokens: 0, cache_read_tokens: 0, cache_write_5m_tokens: 0, cache_write_1h_tokens: 0,
    output_tokens: 0, thinking_tokens: 0, long_prompt: false, cost_usd: 0, duration_ms: 0,
    instructions_version: job?.version ?? null, tools: [], request: null, response: null, thinking: null,
  }
}

async function runJob(ctx: RunContext, jobName: unknown, input: unknown): Promise<RunReply> {
  const job = findJob(jobName)
  const row = newRow(ctx, job)
  /** Ends the run before the model is called: a ledger row with no tokens, and the reason for the app. */
  const stop = async (reason: Exclude<Outcome, 'ok'>, message: string): Promise<RunReply> => {
    row.outcome = reason
    row.error = cutChars(message, RUN_ERROR_MAX)
    await record(ctx, row)
    return { ok: false, reason, message, call: summaryOf(row) }
  }

  // 1 · The rate caps, read early. They come before anything is written, so a flood of requests (bad ones included)
  //     fills neither the ledger nor the bill: over a cap, the answer is "busy" and no row is written. (The
  //     reservation in step 6 checks the caps again, under a lock, for requests that arrive at the same moment.)
  const gate = await readGate(ctx.userDb, row.job, gateScopeOf(ctx))
  if (!gate) {
    ctx.report('the usage could not be read, so nothing was sent')
    return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was sent. Try again in a moment.' }
  }
  const tooMany = rateCapProblem(gate, ctx.caller)
  if (tooMany) return { ok: false, reason: 'busy', message: tooMany }

  // 2 · The job, by name from the fixed list, and its own check of the input.
  if (!job) return stop('bad_input', 'There is no AI job with that name.')
  if (!job.callers.includes(ctx.caller) || job.mode === 'batch') return stop('bad_input', `"${job.title}" can't be started from here.`)
  const prepared = job.prepare(input, ctx.now())
  if ('problem' in prepared) return stop('bad_input', prepared.problem)

  // 3 · The owner's settings. They are stored where the browser can write, so each value is input:
  //     settingsFor puts every one through its list or its limits.
  const stored = await readSettingRows(ctx.userDb, ctx.userId, job.name)
  if (!stored) return stop('error', 'Your AI settings could not be read, so nothing was sent. Try again in a moment.')
  const settings = settingsFor(job, stored.account, stored.job)
  // A job that lets the request pick (the Test bench) still goes through the code's lists: a model or an effort that
  // is not on them is refused here, whatever the job said.
  const choice = prepared.choice ? checkedChoice(prepared.choice) : {}
  if (!choice) return stop('bad_input', 'That model, effort or thinking setting is not one this app offers.')
  if (choice.model) settings.model = choice.model
  if (choice.effort) settings.effort = choice.effort
  row.model = settings.model
  row.effort = settings.effort

  // 4 · The master switch, the job's switch and the API key.
  if (!settings.aiEnabled) return stop('off', 'All AI is switched off in Developer → AI → Settings.')
  if (!settings.enabled) return stop('off', `"${job.title}" is switched off in Developer → AI → Settings.`)
  if (!ctx.provider) return stop('not_configured', 'AI is not set up yet: the server has no API key for it.')

  // 4b · AI last: a job may have work that code does better before any model is asked (reading a recipe page, and
  //      finding the recipe the page already holds). Code that answers alone is no AI call: nothing is reserved or
  //      sent, but a finished zero-cost row is written (so the rate caps count every read), and the reply says
  //      `source: 'page'`.
  let userText = prepared.userText
  if (prepared.early) {
    const earlyStarted = Date.now()
    const early = await runEarly(ctx, prepared.early.bind(prepared))
    if (early.kind === 'stop') return stop(early.outcome, early.message)
    if (early.kind === 'answer') {
      row.outcome = 'ok'
      row.provider = RUN_PAGE_PROVIDER
      row.model = RUN_NO_MODEL
      row.effort = null
      row.cost_usd = 0
      row.duration_ms = Math.max(0, Date.now() - earlyStarted)
      // The link is input and may be long: it goes in only while the owner keeps the text log on.
      if (settings.logText && early.note) row.request = trimForLog({ read_by_code: early.note }, TEXT_LOG_MAX_BYTES)
      await record(ctx, row)
      return { ok: true, job: job.name, result: early.result, source: 'page', call: summaryOf(row) }
    }
    userText = early.userText
  }

  // 4c · A PDF's real size is asked of the provider (count_tokens, free) before anything is reserved: the reservation
  //      holds that count, never a guess from bytes, and a PDF over the cap is refused here. The count leaves out the
  //      web search (the count endpoint takes no server tool), which the reservation adds on its own.
  let documentTokens = 0
  if (prepared.documents?.length && job.acceptsDocument) {
    const counted = await countPrompt(ctx, ctx.provider, buildRequest(job, settings, userText, choice.thinking ?? settings.thinking, COUNT_TIMEOUT_MS, { images: prepared.images, documents: prepared.documents }))
    if (!counted.ok) return stop(counted.outcome, counted.message)
    if (counted.tokens > PDF_PROMPT_TOKENS_MAX) {
      return stop('bad_input', `That PDF is too long for a receipt. Use a photo of the receipt or a shorter PDF.`)
    }
    documentTokens = pdfTokensHeld(counted.tokens)
  }

  // 5 · The request: the fixed instructions first (the provider caches them), then the part that changes.
  const request = buildRequest(job, settings, userText, choice.thinking ?? settings.thinking, ctx.timeoutMs, { images: prepared.images, documents: prepared.documents, webSearchMax: prepared.webSearchMax })

  // 6 · The reservation: the most this call could cost is held against the budget BEFORE it is sent, in one step
  //     under a lock in the database. Requests that arrive at the same moment each hold their own share, so none
  //     can slip past the wall, and a call whose bill is unknown (a timeout) stays charged at that worst case.
  // A photo adds its tokens (worked out from its own header); every search the call may run adds its fee and its results.
  const worstCost = worstCostOf(
    request.model, request.instructions.length + request.userText.length + (request.answerSchema ? JSON.stringify(request.answerSchema).length : 0), request.maxOutputTokens,
    'live', { imageTokens: (prepared.imageTokens ?? 0) + documentTokens, webSearches: request.webSearch?.maxUses ?? 0 },
  )
  const reservation = await reserveCall(ctx.adminDb, {
    userId: ctx.userId, job: job.name, caller: ctx.caller, mode: row.mode, provider: ctx.providerName, model: request.model,
    effort: request.effort, instructionsVersion: job.version, worstCostUsd: worstCost,
    budgetUsd: settings.monthlyBudgetUsd, jobBudgetUsd: settings.jobBudgetUsd,
    perMinute: LIMITS.callsPerMinute, perDay: LIMITS.callsPerDay, callerPerDay: callerDailyCap(ctx.caller),
  })
  if (!reservation) {
    ctx.report('the budget could not be reserved, so nothing was sent')
    return { ok: false, reason: 'error', message: 'The AI budget could not be checked, so nothing was sent. Try again in a moment.' }
  }
  if (reservation.kind === 'busy') {
    return { ok: false, reason: 'busy', message: `That is more than ${LIMITS.callsPerMinute} AI calls in a minute, ${LIMITS.callsPerDay} today, or ${callerDailyCap(ctx.caller)} in 24 hours from ${ctx.caller === 'app' ? 'the app' : 'this device'}. Wait a moment and try again.` }
  }
  // From here the database holds a row for this call: it is finished by id, never written a second time.
  row.id = reservation.id
  if (reservation.kind === 'budget') {
    row.outcome = 'budget'
    row.error = cutChars(reservationBudgetProblem(settings, job.title), RUN_ERROR_MAX)
    return { ok: false, reason: 'budget', message: reservationBudgetProblem(settings, job.title), call: summaryOf(row) }
  }
  const started = Date.now()
  const answer = await send(ctx, ctx.provider, request)
  row.duration_ms = Math.max(0, Date.now() - started)
  // One step is the whole run in phase 1. Phase 4 puts the tool loop here: while the answer asks for a tool,
  // run the tool as the owner, add its result to the conversation and send again. Each round gets its own
  // ledger row with this run_id and the next step number.

  // 7 · Reading the answer: how it ended first, then the job's own check of what it says.
  const verdict = judge(answer, prepared, settings.maxOutputTokens)

  // 8 · The ledger: what it cost, how long it took, how it ended. The cost comes from this code's price table.
  const usage = answer.ok ? answer.usage : RUN_NO_TOKENS
  const searches = answer.ok ? answer.webSearches : 0
  const price = costOf(usage, request.model, row.mode, searches)
  // The searches the call really ran are logged (the count, never what was found).
  if (searches > 0) row.tools = [{ name: 'web_search', searches }]
  row.outcome = verdict.ok ? 'ok' : verdict.outcome
  // The provider's own explanation goes into the row only while the text log is on: with it off, the row holds
  // nothing but our fixed sentence.
  row.error = verdict.ok ? null : cutChars(hideSecrets(settings.logText ? verdict.logLine : verdict.message, ctx.secrets), RUN_ERROR_MAX)
  row.request_id = answer.requestId
  row.stop_reason = answer.ok ? answer.stopReason : null
  row.served_model = answer.ok ? answer.servedModel : null
  row.input_tokens = usage.inputTokens
  row.cache_read_tokens = usage.cacheReadTokens
  row.cache_write_5m_tokens = usage.cacheWrite5mTokens
  row.cache_write_1h_tokens = usage.cacheWrite1hTokens
  row.output_tokens = usage.outputTokens
  row.thinking_tokens = usage.thinkingTokens
  row.long_prompt = price.longPrompt
  // A failure that may have been billed (a timeout, a network error, a 5xx, an unknown fault) stays at the worst case.
  row.cost_usd = !answer.ok && RUN_MAY_BE_BILLED.includes(answer.kind) ? worstCost : price.costUsd
  if (settings.logText) {
    // The text log, only while the owner keeps it on: what was sent, and what came back.
    row.request = trimForLog({
      model: request.model, effort: request.effort, max_output_tokens: request.maxOutputTokens,
      instructions_version: job.version, instructions: request.instructions, user_text: request.userText,
      answer_schema: request.answerSchema, thinking: request.thinking,
      // A photo is never kept in the log: only how many were sent and how big.
      ...(request.images?.length ? { images: request.images.map(i => ({ media_type: i.mediaType, base64_chars: i.base64.length })) } : {}),
      ...(request.documents?.length ? { documents: request.documents.map(d => ({ media_type: 'application/pdf', base64_chars: d.base64.length })) } : {}),
      ...(request.webSearch ? { web_search_max_uses: request.webSearch.maxUses } : {}),
      // The request as the provider part built it (the cache mark, the thinking setting, the time limit …).
      ...(answer.sent ? { sent_to_provider: answer.sent } : {}),
    }, TEXT_LOG_MAX_BYTES)
    if (answer.ok) {
      row.response = trimForLog({ text: answer.text, ...(answer.refusal ? { refusal: answer.refusal } : {}) }, TEXT_LOG_MAX_BYTES)
      row.thinking = answer.thinking ? trimText(answer.thinking, TEXT_LOG_MAX_BYTES) : null
    }
  }
  await finish(ctx, row)

  // 9 · The reply. A message leaves only through hideSecrets.
  if (verdict.ok) return { ok: true, job: job.name, result: verdict.result, call: summaryOf(row) }
  return { ok: false, reason: verdict.outcome, message: hideSecrets(verdict.message, ctx.secrets), call: summaryOf(row) }
}

function gateScopeOf(ctx: RunContext): GateScope {
  return ctx.readAs === 'owner' ? { kind: 'owner' } : { kind: 'server', userId: ctx.userId, caller: ctx.caller, now: ctx.now() }
}

/**
 * The request a run sends, from the job, the checked settings and the live text. The Test bench's token count
 * builds it the same way, so the number it shows is the number of the request that would be sent.
 */
function buildRequest(
  job: JobDefinition, settings: RunSettings, userText: string, thinking: 'adaptive' | 'off', timeoutOverride?: number,
  extra: { images?: RequestImage[]; documents?: RequestDocument[]; webSearchMax?: number } = {},
): ModelRequest {
  return {
    ...(extra.images?.length && job.acceptsImage ? { images: extra.images } : {}),
    ...(extra.documents?.length && job.acceptsDocument ? { documents: extra.documents } : {}),
    // The tool only for a job whose definition names it (a job's prepare alone can never switch a tool on).
    ...(extra.webSearchMax && extra.webSearchMax > 0 && job.tools?.some(t => t.name === 'web_search') ? { webSearch: { maxUses: Math.min(Math.floor(extra.webSearchMax), WEB_SEARCH_MAX_USES) } } : {}),
    model: settings.model,
    maxOutputTokens: settings.maxOutputTokens,
    effort: settings.effort,
    instructions: job.instructions,
    userText,
    answerSchema: job.enforceAnswerSchema ? job.answerSchema : null,
    thinking,
    // Diagnose's own limit wins; then the job's own (a phone shortcut gives up sooner); else the limit follows the
    // job's longest answer.
    timeoutMs: timeoutOverride ?? job.timeLimitMs ?? requestTimeoutMs(settings.maxOutputTokens),
  }
}

/**
 * The Test bench's "what will this cost": the prompt tokens of the request a run of `jobName` would send, counted by
 * the provider without generating anything (free, nothing reserved, nothing written). The same checks as a run come
 * first: the caller, the input, the lists, the switch and the key; and it refuses while the account is at a rate cap.
 */
async function countJob(ctx: RunContext, jobName: unknown, input: unknown): Promise<CountReply> {
  const job = findJob(jobName)
  if (!job || !job.pickable || !job.callers.includes(ctx.caller)) return { ok: false, reason: 'bad_input', message: 'There is nothing to count for that job.' }
  const prepared = job.prepare(input, ctx.now())
  if ('problem' in prepared) return { ok: false, reason: 'bad_input', message: prepared.problem }
  const choice = prepared.choice ? checkedChoice(prepared.choice) : {}
  if (!choice) return { ok: false, reason: 'bad_input', message: 'That model, effort or thinking setting is not one this app offers.' }
  const gate = await readGate(ctx.userDb, job.name, gateScopeOf(ctx))
  if (!gate) return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was counted. Try again in a moment.' }
  const tooMany = rateCapProblem(gate, ctx.caller)
  if (tooMany) return { ok: false, reason: 'busy', message: tooMany }
  const stored = await readSettingRows(ctx.userDb, ctx.userId, job.name)
  if (!stored) return { ok: false, reason: 'error', message: 'Your AI settings could not be read, so nothing was counted. Try again in a moment.' }
  const settings = settingsFor(job, stored.account, stored.job)
  if (choice.model) settings.model = choice.model
  if (choice.effort) settings.effort = choice.effort
  if (!settings.aiEnabled) return { ok: false, reason: 'off', message: 'All AI is switched off in Developer → AI → Settings.' }
  if (!settings.enabled) return { ok: false, reason: 'off', message: `"${job.title}" is switched off in Developer → AI → Settings.` }
  if (!ctx.provider) return { ok: false, reason: 'not_configured', message: 'AI is not set up yet: the server has no API key for it.' }
  const thinking = choice.thinking ?? settings.thinking
  // The count costs nothing, but it is a request to Anthropic: a few a minute, counted from the ledger (security
  // review G3). Each count leaves a zero-cost row (stop reason 'count_tokens') that this check reads and that the
  // account's own caps count like any call. Two counts at the same instant may both pass: the cap is small and the
  // count is free, so it is read without a lock.
  const recent = await countRecentCalls(ctx.userDb, ctx.userId, job.name, new Date(ctx.now().getTime() - 60_000).toISOString(), COUNT_STOP_REASON)
  if (recent === null) return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was counted. Try again in a moment.' }
  if (recent >= LIMITS.countsPerMinute) return { ok: false, reason: 'busy', message: `That is more than ${LIMITS.countsPerMinute} token counts in a minute. Wait a moment and try again.` }
  const started = Date.now()
  let counted
  try {
    counted = await ctx.provider.countTokens(buildRequest(job, settings, prepared.userText, thinking, COUNT_TIMEOUT_MS))
  } catch (error) {
    ctx.report(`the provider part threw: ${errorPlace(error)}`)
    counted = null
  }
  const row = newRow(ctx, job)
  row.model = settings.model
  row.effort = settings.effort
  row.outcome = counted?.ok ? 'ok' : 'error'
  row.stop_reason = COUNT_STOP_REASON
  row.error = counted?.ok ? null : 'The token count failed.'
  row.duration_ms = Math.max(0, Date.now() - started)
  await record(ctx, row)
  if (!counted) return { ok: false, reason: 'error', message: 'The token count failed unexpectedly. Try again in a moment.' }
  if (!counted.ok) return { ok: false, reason: 'error', message: hideSecrets(counted.message, ctx.secrets) }
  return { ok: true, input_tokens: counted.inputTokens, model: settings.model, effort: settings.effort, thinking }
}

// The ledger row a token count leaves (zero tokens, zero cost): the app labels it "Token count", and the cap reads it.
const COUNT_STOP_REASON = 'count_tokens'

// The free count waits at most this long: it only reads the prompt, it writes no answer.
const COUNT_TIMEOUT_MS = 20_000

/**
 * The provider's count of a request's prompt tokens (free). A request the provider refuses outright (a PDF it cannot
 * read) is the owner's file, not a fault; any other failure stops the run with the provider's scrubbed sentence.
 */
async function countPrompt(ctx: RunContext, provider: Provider, request: ModelRequest): Promise<{ ok: true; tokens: number } | { ok: false; outcome: 'bad_input' | 'error'; message: string }> {
  try {
    const counted = await provider.countTokens(request)
    // Fail closed: a count that is missing or zero says nothing about the PDF, so nothing is reserved on it.
    if (counted.ok && counted.inputTokens > 0) return { ok: true, tokens: counted.inputTokens }
    if (counted.ok) return { ok: false, outcome: 'error', message: 'The PDF could not be checked: Anthropic gave no token count for it. Try again, or use a photo.' }
    if (counted.kind === 'refused_request') return { ok: false, outcome: 'bad_input', message: 'That PDF could not be read. Try a photo of the receipt, or a PDF saved without a password.' }
    return { ok: false, outcome: 'error', message: hideSecrets(counted.message, ctx.secrets) }
  } catch (error) {
    ctx.report(`the provider part threw: ${errorPlace(error)}`)
    return { ok: false, outcome: 'error', message: 'The PDF could not be checked unexpectedly. Try again in a moment.' }
  }
}

/** A job's step before the model. One that throws (it shouldn't) stops the run with a plain sentence. */
async function runEarly(ctx: RunContext, early: (env: PageEnv) => Promise<EarlyStep>): Promise<EarlyStep> {
  try {
    return await early(ctx.page)
  } catch (error) {
    ctx.report(`a job's step before the model threw: ${errorPlace(error)}`)
    return { kind: 'stop', outcome: 'error', message: 'The step before the AI call failed unexpectedly. Try again in a moment.' }
  }
}

/** One request to the model. A provider that throws (it shouldn't) is a failed call, not a crashed run. */
async function send(ctx: RunContext, provider: Provider, request: ModelRequest): Promise<ModelAnswer | ModelFailure> {
  try {
    return await provider.send(request)
  } catch (error) {
    ctx.report(`the provider part threw: ${errorPlace(error)}`)
    return { ok: false, kind: 'unknown', status: null, message: 'The AI call failed unexpectedly.', detail: '', requestId: null, sent: null }
  }
}

/** What an answer amounts to: a checked result, or how it failed. */
type Verdict =
  | { ok: true; result: Record<string, unknown> }
  // `message` is for the app: one plain sentence. `logLine` is for the ledger: the message, with the
  // provider's own explanation when there is one.
  | { ok: false; outcome: Exclude<Outcome, 'ok'>; message: string; logLine: string }

/** Only a complete answer that passes the job's own check gives a result. */
function judge(answer: ModelAnswer | ModelFailure, prepared: PreparedRun, maxOutputTokens: number): Verdict {
  const failed = (outcome: Exclude<Outcome, 'ok'>, message: string, detail = ''): Verdict =>
    ({ ok: false, outcome, message, logLine: detail ? `${message} — ${detail}` : message })
  if (!answer.ok) return failed('error', answer.message, answer.detail)
  if (answer.ending === 'refused') return failed('refused', 'The model declined to answer this one.', answer.refusal)
  if (answer.ending === 'cut_off') {
    return failed('cut_off', `The answer was cut off at its limit of ${maxOutputTokens} tokens. Raise the longest answer for this job in Developer → AI → Settings.`)
  }
  if (answer.ending !== 'complete') return failed('error', `The model stopped in a way this app does not handle yet (${answer.stopReason}).`)
  let check: AnswerCheck
  try {
    check = prepared.read(answer.text, { thinking: answer.thinking, servedModel: answer.servedModel, webSearches: answer.webSearches, searchUrls: answer.searchUrls ?? [] })
  } catch {
    check = { ok: false, problem: 'its check failed' }
  }
  // A failed check is never repaired: the answer is thrown away and the owner is told.
  return check.ok ? { ok: true, result: check.result } : failed('invalid', `The model's answer could not be used: ${check.problem}.`)
}

/**
 * Puts the real numbers on the reserved row. A failed update never fails the answer and is said in the server log;
 * the row then keeps its worst-case cost, so the budget is only ever counted too much, never too little.
 */
async function finish(ctx: RunContext, row: CallRow): Promise<void> {
  const problem = await finishCall(ctx.adminDb, row)
  if (problem) ctx.report(`a call could not be finished in the ledger (it stays at its reserved cost): ${problem}`)
}

/** Writes the row. A failed write never fails the answer, but it is said in the server log. */
async function record(ctx: RunContext, row: CallRow): Promise<void> {
  const problem = await writeCall(ctx.adminDb, row)
  if (problem) ctx.report(`a call was not written to the ledger: ${problem}`)
}

// ═══ supabase/claude-src/batch.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · the batch flow (weekly report, phase 3)
//
//  Two steps, run by two timers (migration 196) or by the app's buttons:
//
//    makeWeeklyReport  — Monday 05:00 Oslo (Sunday is complete): the week's figures (code), the request, the reservation at
//                        the BATCH price (half), one batch with one request, and the report row (`queued`) holding the
//                        batch id. The button makes the last full week again when its real report is missing or failed.
//    checkReports      — every 15 minutes while a report is queued or a push is owed: ask whether the batch ended; when it
//                        did, read the one result line (found by `custom_id` = the ledger row's id, unique per submission,
//                        never by position), check the text, write the report and correct the ledger row to the real cost
//                        at the batch price. The push is a separate step: owed from the moment the real report is done,
//                        sent at the first check from 07:00 Oslo time. Once: a claim makes one check own a report, and the
//                        push is stamped before it is sent. Only the scheduled (real) report of the owner's week pushes.
//
//  A failure never loops. A scheduled make is tried once a week (a report row of that week stops the second run); a
//  check that finds the batch failed, expired, cancelled or unusable ends the report as `failed` for good, keeps the
//  worst case in the ledger (the safe side) and says why in the row. The only thing a check repeats is asking again
//  while Anthropic has not finished.
//
//  The model's text is data: it goes through `readWeeklyReport` (length, five fixed headings, no link or markup), and
//  nothing it says is ever used as an id, an address or a target. The batch id comes only from the report row.
// ─────────────────────────────────────────────────────────────────────────────

const BATCH_REQUEST_MS = 30_000
const BATCH_STATUS_MS = 20_000
// Anthropic ends a batch at 24 hours at the latest (what is not done expires). Past 26 hours the report is given up.
const BATCH_GIVE_UP_MS = 26 * 3_600_000
// A report row with no batch id this old never got its batch registered.
const BATCH_NO_ID_MS = 30 * 60_000
// A check that died keeps its claim this long.
const CLAIM_MS = 10 * 60_000
const FAILURE_MAX = 300
// A failure that may have been billed (the request may have reached Anthropic) stays at the reserved worst case.
const MAY_BE_BILLED = ['network', 'timeout', 'overloaded', 'provider_fault', 'unknown']

const PUSH_FAILED_BODY = "This week's report could not be made. Developer → AI → Learn → Batches says why."

/** A ledger row for this job, with every column at "nothing happened yet" (the reservation writes the real one). */
function ledgerRow(ctx: RunContext, model: string, job: JobDefinition = WEEKLY_REPORT_JOB): CallRow {
  return {
    id: ctx.newId(), user_id: ctx.userId, run_id: ctx.newId(), step: 1, job: job.name, caller: ctx.caller, mode: 'batch',
    provider: ctx.providerName, model, served_model: null, effort: null, outcome: 'error', stop_reason: null, error: null, request_id: null,
    input_tokens: 0, cache_read_tokens: 0, cache_write_5m_tokens: 0, cache_write_1h_tokens: 0, output_tokens: 0, thinking_tokens: 0,
    long_prompt: false, cost_usd: 0, duration_ms: 0, instructions_version: job.version, tools: [], request: null, response: null, thinking: null,
  }
}

// ── Step 1: make ────────────────────────────────────────────────────────────

async function makeWeeklyReport(ctx: RunContext): Promise<ReportMakeReply> {
  const job = WEEKLY_REPORT_JOB
  const scheduled = ctx.caller === 'schedule'
  if (!job.callers.includes(ctx.caller)) return { ok: false, reason: 'bad_input', message: `"${job.title}" can't be started from here.` }
  const now = ctx.now()
  // Which week, and whose report it is. The timer makes the real report of the week that just ended. The button makes that
  // same real report again when it is missing or failed ("redo"); when it is ready, a test copy of it (Monday, Tuesday) or
  // the week so far: those are the button's own rows, never the real one, and they are never pushed.
  let week = scheduled ? scheduledReportWeek(now) : null
  let madeBy: 'schedule' | 'app' = 'schedule'
  let kind: 'scheduled' | 'redo' | 'copy' | 'so_far' = 'scheduled'
  if (!scheduled) {
    const last = lastFullWeek(now)
    const real = await findReport(ctx.adminDb, ctx.userId, last.start, 'schedule')
    if (real === undefined) return { ok: false, reason: 'error', message: 'The reports could not be read, so nothing was queued. Try again in a moment.' }
    if (real?.status === 'queued') return { ok: true, queued: false, skipped: 'already_queued', week_start: last.start }
    const plan = manualReportPlan(now, real?.status === 'ready')
    week = plan.week
    kind = plan.kind
    madeBy = plan.kind === 'redo' ? 'schedule' : 'app'
  }
  if (!week) return { ok: true, queued: false, skipped: 'not_the_time', week_start: null }
  // Only the owner's real report is announced on the owner's phone (a button copy, another account: never).
  const pushDue = madeBy === 'schedule' && !!ctx.push

  // A report of this week by this maker already exists: the second timer run, a repeated tap. A scheduled report is
  // never made twice by the timer (a failed one is not retried either: no loop); the button may redo a failed real report
  // and any copy of its own.
  const existing = await findReport(ctx.adminDb, ctx.userId, week.start, madeBy)
  if (existing === undefined) return { ok: false, reason: 'error', message: 'The reports could not be read, so nothing was queued. Try again in a moment.' }
  if (existing?.status === 'queued') return { ok: true, queued: false, skipped: 'already_queued', week_start: week.start }
  if (existing && scheduled) return { ok: true, queued: false, skipped: 'already_made', week_start: week.start }
  if (existing?.status === 'ready' && madeBy === 'schedule') return { ok: true, queued: false, skipped: 'already_made', week_start: week.start }

  // The ledger row of a request that stops before anything is queued: no tokens, and the reason.
  const stop = async (reason: 'off' | 'not_configured' | 'busy' | 'error' | 'budget', message: string, model: string): Promise<ReportMakeReply> => {
    if (reason !== 'busy') {
      const row = ledgerRow(ctx, model)
      row.outcome = reason
      row.error = cutChars(message, FAILURE_MAX)
      const problem = await writeCall(ctx.adminDb, row)
      if (problem) ctx.report(`a call was not written to the ledger: ${problem}`)
    }
    // The timer's one try is recorded, so the second run of the night and the next check know it ended here.
    if (scheduled && reason !== 'busy') await recordFailedWeek(ctx, week.start, existing, message)
    return { ok: false, reason, message }
  }

  const gate = await readGate(ctx.userDb, job.name, gateScopeOf(ctx))
  if (!gate) {
    ctx.report('the usage could not be read, so nothing was queued')
    return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was queued. Try again in a moment.' }
  }
  const tooMany = rateCapProblem(gate, ctx.caller)
  if (tooMany) return { ok: false, reason: 'busy', message: tooMany }
  const stored = await readSettingRows(ctx.userDb, ctx.userId, job.name)
  if (!stored) return stop('error', 'Your AI settings could not be read, so nothing was queued. Try again in a moment.', job.defaults.model)
  const settings = settingsFor(job, stored.account, stored.job)
  if (!settings.aiEnabled) return stop('off', 'All AI is switched off in Developer → AI → Settings.', settings.model)
  if (!settings.enabled) return stop('off', `"${job.title}" is switched off in Developer → AI → Settings.`, settings.model)
  if (!ctx.provider) return stop('not_configured', 'AI is not set up yet: the server has no API key for it.', settings.model)

  // AI last: the figures come first, from the database, by code.
  const facts = await readWeekFacts(ctx.adminDb, ctx.userId, week, kind === 'so_far')
  if (facts.unreadable.length === 4) return stop('error', 'The week could not be read from the database, so nothing was queued.', settings.model)
  if (!hasAnyData(facts)) {
    if (scheduled) await recordFailedWeek(ctx, week.start, existing, 'There was no data to report on this week.')
    return { ok: true, queued: false, skipped: 'no_data', week_start: week.start }
  }
  const userText = factsText(facts)
  const request = buildRequest(job, settings, userText, settings.thinking)
  // The most this request could cost, at the batch price: held against the budget before anything is sent.
  const worstCost = worstCostOf(request.model, request.instructions.length + request.userText.length, request.maxOutputTokens, 'batch')

  // The report row first: the unique (user, week, maker) key is what stops two makes of one week at the same moment.
  let reportId = ctx.newId()
  // What the model reads is saved with the figures: the Batches view shows it as "Figures sent".
  const factsJson = { ...facts, sent_text: userText, kind } as unknown as Record<string, unknown>
  if (existing) {
    if (!(await requeueReport(ctx.adminDb, ctx.userId, existing.id, factsJson, now.toISOString(), false))) {
      return { ok: true, queued: false, skipped: 'already_queued', week_start: week.start }
    }
    reportId = existing.id
  } else {
    const added = await insertReport(ctx.adminDb, { id: reportId, user_id: ctx.userId, week_start: week.start, made_by: madeBy, facts: factsJson, push_due: false })
    if (added === 'exists') return { ok: true, queued: false, skipped: 'already_queued', week_start: week.start }
    if (added === 'error') return { ok: false, reason: 'error', message: 'The report could not be saved, so nothing was queued. Try again in a moment.' }
  }
  const fail = (message: string) => patchReport(ctx.adminDb, ctx.userId, reportId, { status: 'failed', failure: cutChars(message, FAILURE_MAX), ready_at: ctx.now().toISOString() }, true)

  const reservation = await reserveCall(ctx.adminDb, {
    userId: ctx.userId, job: job.name, caller: ctx.caller, mode: 'batch', provider: ctx.providerName, model: request.model,
    effort: request.effort, instructionsVersion: job.version, worstCostUsd: worstCost,
    budgetUsd: settings.monthlyBudgetUsd, jobBudgetUsd: settings.jobBudgetUsd,
    perMinute: LIMITS.callsPerMinute, perDay: LIMITS.callsPerDay, callerPerDay: callerDailyCap(ctx.caller),
  })
  if (!reservation) {
    ctx.report('the budget could not be reserved, so nothing was queued')
    await fail('The AI budget could not be checked, so nothing was queued.')
    return { ok: false, reason: 'error', message: 'The AI budget could not be checked, so nothing was queued. Try again in a moment.', report_id: reportId }
  }
  if (reservation.kind === 'busy') {
    await fail('Too many AI calls at the moment, so nothing was queued.')
    return { ok: false, reason: 'busy', message: `That is more than ${LIMITS.callsPerMinute} AI calls in a minute, ${LIMITS.callsPerDay} today, or ${callerDailyCap(ctx.caller)} in 24 hours. Wait a moment and try again.`, report_id: reportId }
  }
  if (reservation.kind === 'budget') {
    const message = reservationBudgetProblem(settings, job.title)
    await fail(message)
    return { ok: false, reason: 'budget', message, report_id: reportId }
  }
  const callId = reservation.id
  await patchReport(ctx.adminDb, ctx.userId, reportId, { call_id: callId }, true)

  // One batch, one request: its custom_id is the ledger row's id (unique per submission, a uuid with nothing of the owner's
  // in it), so a re-made report can never be answered by the line of an earlier batch.
  const started = Date.now()
  let submitted
  try {
    submitted = await ctx.provider.submitBatch([{ customId: callId, request }], BATCH_REQUEST_MS)
  } catch (error) {
    ctx.report(`the provider part threw: ${errorPlace(error)}`)
    submitted = { ok: false as const, kind: 'unknown' as const, status: null, message: 'The batch could not be queued: the AI call failed unexpectedly.', detail: '', requestId: null, sent: null }
  }
  if (!submitted.ok) {
    const message = hideSecrets(submitted.message, ctx.secrets)
    await fail(message)
    const patch: Partial<CallRow> = {
      outcome: 'error', stop_reason: 'batch_not_queued', error: cutChars(hideSecrets(settings.logText ? `${submitted.message} ${submitted.detail}`.trim() : submitted.message, ctx.secrets), FAILURE_MAX),
      duration_ms: Math.max(0, Date.now() - started),
      ...(MAY_BE_BILLED.includes(submitted.kind) ? {} : { cost_usd: 0 }),
    }
    const problem = await patchCall(ctx.adminDb, ctx.userId, callId, patch)
    if (problem) ctx.report(`a call could not be finished in the ledger (it stays at its reserved cost): ${problem}`)
    // The real report the owner expects: its failure is announced too (from 07:00).
    if (pushDue) await patchReport(ctx.adminDb, ctx.userId, reportId, { push_due: true })
    return { ok: false, reason: 'failed', message, report_id: reportId }
  }
  if (!(await patchReport(ctx.adminDb, ctx.userId, reportId, { batch_id: submitted.batchId }, true))) {
    ctx.report('the batch was queued but its id could not be saved: the report will be given up after 26 hours (its worst case stays in the ledger)')
  }
  // The text log of the reserved row, while the owner keeps it on. The row stays 'pending' (counted at its worst case).
  const logPatch: Partial<CallRow> = {
    effort: request.effort, stop_reason: 'batch_queued', duration_ms: 0,
    ...(settings.logText ? { request: trimForLog({
      model: request.model, effort: request.effort, max_output_tokens: request.maxOutputTokens, instructions_version: job.version,
      instructions: request.instructions, user_text: request.userText, thinking: request.thinking, mode: 'batch',
    }, TEXT_LOG_MAX_BYTES) } : {}),
  }
  const problem = await patchCall(ctx.adminDb, ctx.userId, callId, logPatch)
  if (problem) ctx.report(`a batch's ledger row could not be updated: ${problem}`)
  return { ok: true, queued: true, report_id: reportId, week_start: week.start, kind }
}

/** The scheduled try of a week that ended without queueing anything: a failed report row says why (no push). */
async function recordFailedWeek(ctx: RunContext, weekStart: string, existing: ReportRow | null, message: string): Promise<void> {
  const id = ctx.newId()
  const added = existing ? 'exists' : await insertReport(ctx.adminDb, { id, user_id: ctx.userId, week_start: weekStart, made_by: 'schedule', facts: {}, push_due: false })
  if (added === 'error') { ctx.report('the failed week could not be recorded'); return }
  await patchReport(ctx.adminDb, ctx.userId, existing ? existing.id : id, { status: 'failed', failure: cutChars(message, FAILURE_MAX), ready_at: ctx.now().toISOString() }, true)
}

// ── Step 2: check ───────────────────────────────────────────────────────────

async function checkReports(ctx: RunContext): Promise<ReportCheckReply> {
  if (!ctx.provider) return { ok: false, message: 'AI is not set up yet: the server has no API key for it.' }
  const now = ctx.now()
  await releaseStaleClaims(ctx.adminDb, ctx.userId, new Date(now.getTime() - CLAIM_MS).toISOString())
  const queued = await queuedReports(ctx.adminDb, ctx.userId)
  if (!queued) return { ok: false, message: 'The reports could not be read. Try again in a moment.' }
  const tally = { checked: 0, ready: 0, failed: 0, waiting: 0, pushed: 0 }
  for (const report of queued) {
    if (!(await claimReport(ctx.adminDb, ctx.userId, report.id, report.created_at, now.toISOString()))) continue
    tally.checked += 1
    let outcome: 'ready' | 'failed' | 'waiting'
    try {
      outcome = await checkOne(ctx, report)
    } catch (error) {
      ctx.report(`a report check threw: ${errorPlace(error)}`)
      outcome = 'waiting'
    }
    tally[outcome] += 1
    if (outcome === 'waiting') await releaseClaim(ctx.adminDb, ctx.userId, report.id, report.created_at)
  }
  tally.pushed = await pushPending(ctx)
  return { ok: true, ...tally }
}

async function checkOne(ctx: RunContext, report: ReportRow): Promise<'ready' | 'failed' | 'waiting'> {
  const provider = ctx.provider
  if (!provider) return 'waiting'
  const age = ctx.now().getTime() - Date.parse(report.created_at)
  const tooOld = Number.isFinite(age) && age > BATCH_GIVE_UP_MS
  const giveUp = async (message: string, stopReason: string): Promise<'failed'> => {
    await endFailed(ctx, report, message, stopReason, true)
    return 'failed'
  }
  if (!report.batch_id) {
    return age > BATCH_NO_ID_MS || tooOld ? giveUp('The batch was never registered, so there is nothing to read.', 'batch_not_registered') : 'waiting'
  }
  const status = await provider.batchStatus(report.batch_id, BATCH_STATUS_MS)
  if (!status.ok) return tooOld ? giveUp('Anthropic could not be asked about the batch for more than a day.', 'batch_unreachable') : 'waiting'
  if (status.status !== 'ended') return tooOld ? giveUp('The batch did not end within a day.', 'batch_expired') : 'waiting'

  const results = await provider.batchResults(report.batch_id, BATCH_REQUEST_MS)
  if (!results.ok) return tooOld ? giveUp('The results could not be read for more than a day.', 'batch_unreachable') : 'waiting'
  // Lines come in any order: the one that is ours is found by its custom_id, compared exactly. Others are ignored.
  const line = results.lines.find(l => l.customId === report.call_id)
  if (!line || !report.call_id) return giveUp('The batch ended without a result for this report.', 'batch_no_result')
  if (line.kind !== 'succeeded') {
    const word = line.kind === 'errored' ? 'failed' : line.kind === 'expired' ? 'expired before it was answered' : 'was cancelled'
    return giveUp(`The batch request ${word}.`, `batch_${line.kind}`)
  }
  const answer = line.answer
  const stored = await readSettingRows(ctx.userDb, ctx.userId, WEEKLY_REPORT_JOB.name)
  const logText = stored ? settingsFor(WEEKLY_REPORT_JOB, stored.account, stored.job).logText : false

  const failure = answerProblem(answer)
  const check = failure ? null : readWeeklyReport(answer.text)
  const bad = failure ?? (check && !check.ok ? `The model's answer could not be used: ${check.problem}.` : null)
  // The real numbers, at the batch price. A model that is not on the price list is charged as the dearest one.
  const price = costOf(answer.usage, answer.servedModel ?? WEEKLY_REPORT_JOB.defaults.model, 'batch')
  const real: Partial<CallRow> = {
    served_model: answer.servedModel, request_id: answer.requestId, stop_reason: answer.stopReason,
    input_tokens: answer.usage.inputTokens, cache_read_tokens: answer.usage.cacheReadTokens,
    cache_write_5m_tokens: answer.usage.cacheWrite5mTokens, cache_write_1h_tokens: answer.usage.cacheWrite1hTokens,
    output_tokens: answer.usage.outputTokens, thinking_tokens: answer.usage.thinkingTokens, long_prompt: price.longPrompt,
    cost_usd: price.costUsd, duration_ms: Number.isFinite(age) ? Math.max(0, Math.round(age)) : 0,
    ...(logText ? { response: trimForLog({ text: answer.text, ...(answer.refusal ? { refusal: answer.refusal } : {}) }, TEXT_LOG_MAX_BYTES), thinking: answer.thinking ? trimText(answer.thinking, TEXT_LOG_MAX_BYTES) : null } : {}),
  }
  if (bad || !check || !check.ok) {
    // The model answered, so it was billed: the row gets the real cost, and the report fails.
    await ledgerFinish(ctx, report, { ...real, outcome: answer.ending === 'refused' ? 'refused' : answer.ending === 'cut_off' ? 'cut_off' : 'invalid', error: cutChars(hideSecrets(bad ?? 'unusable', ctx.secrets), FAILURE_MAX) })
    await endFailed(ctx, report, bad ?? 'The answer could not be used.', null, false)
    return 'failed'
  }
  await ledgerFinish(ctx, report, { ...real, outcome: 'ok', error: null })
  const text = String(check.result.text)
  // The push is owed from now on (the real report of the owner's week only) and goes out from 07:00 (pushPending). The
  // write is tied to the report this check read: a report made again meanwhile has a new created_at and is not touched.
  if (!(await patchReport(ctx.adminDb, ctx.userId, report.id, { status: 'ready', content: text, failure: null, ready_at: ctx.now().toISOString(), claimed_at: null, push_due: report.made_by === 'schedule' && !!ctx.push }, true, report.created_at))) {
    ctx.report('a finished report could not be saved (it was made again meanwhile, or the write failed)')
    return 'waiting'
  }
  return 'ready'
}

/** Why a model's answer is no report, or null. */
function answerProblem(answer: ModelAnswer): string | null {
  if (answer.ending === 'refused') return 'The model declined to write this report.'
  if (answer.ending === 'cut_off') return 'The report was cut off at its length limit.'
  if (answer.ending !== 'complete') return `The model stopped in a way this app does not handle yet (${answer.stopReason}).`
  return null
}

/** The ledger row, corrected with what is now known. A failed write leaves the reserved worst case: the safe side. */
async function ledgerFinish(ctx: RunContext, report: ReportRow, patch: Partial<CallRow>): Promise<void> {
  if (!report.call_id) { ctx.report('a report has no ledger row to correct'); return }
  const problem = await patchCall(ctx.adminDb, ctx.userId, report.call_id, patch)
  if (problem) ctx.report(`a call could not be finished in the ledger (it stays at its reserved cost): ${problem}`)
}

/**
 * Ends a report as failed, for good. With `keepWorstCase` the ledger row keeps the reserved cost (the batch ended
 * without an answer we can price: errored, expired, cancelled or gone) and says how it ended.
 */
async function endFailed(ctx: RunContext, report: ReportRow, message: string, stopReason: string | null, keepWorstCase: boolean): Promise<void> {
  if (keepWorstCase) await ledgerFinish(ctx, report, { outcome: 'error', stop_reason: stopReason, error: cutChars(message, FAILURE_MAX) })
  // A failed real report is announced too (from 07:00): the owner expects one on Monday.
  await patchReport(ctx.adminDb, ctx.userId, report.id, {
    status: 'failed', failure: cutChars(message, FAILURE_MAX), ready_at: ctx.now().toISOString(), claimed_at: null, push_due: report.made_by === 'schedule' && !!ctx.push,
  }, true, report.created_at)
}

/**
 * The pushes that are owed: sent only from 07:00 to 22:00 Oslo time (a report finished at 05:30 is announced at 07:00). Each is
 * stamped before it is sent, so two overlapping checks send one and a push that fails is not repeated. Only the owner's real
 * reports are ever owed (`push_due`), and `ctx.push` is null for any other account (main.ts).
 */
async function pushPending(ctx: RunContext): Promise<number> {
  if (!ctx.push || !pushWindowOpen(ctx.now())) return 0
  const due = await pendingPushes(ctx.adminDb, ctx.userId)
  if (!due) return 0
  let sent = 0
  for (const report of due) {
    if (!(await claimPush(ctx.adminDb, ctx.userId, report.id, report.created_at, ctx.now().toISOString()))) continue
    const message = report.status === 'ready'
      ? { title: 'Weekly report', body: `Your report for ${dmy(report.week_start)} – ${dmy(shiftDay(report.week_start, 6))} is ready.`, url: `#/home?report=${report.id}` }
      : { title: 'Weekly report', body: PUSH_FAILED_BODY, url: '#/developer?tab=ai&view=learn&learn=batches' }
    let delivered = false
    try {
      delivered = await ctx.push(message)
    } catch (error) {
      ctx.report(`the push threw: ${errorPlace(error)}`)
    }
    if (delivered) sent += 1
    else ctx.report('a report push was not delivered (it is not repeated)')
  }
  return sent
}

// ═══ supabase/claude-src/suggest-batch.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · the weekly suggestions' batch (phase 4c, migration 199)
//
//  The same two steps as the weekly report (batch.ts), small:
//    makeWeeklySuggestions  — Monday 05:00 Oslo (after the report, from the same timer) or the Suggestions view's button:
//                             count the repeats in the ledger with code (`ai_suggest_patterns`), and only when something
//                             repeats, queue ONE request at the batch price, reserved against the budget first.
//    checkSuggestRuns       — read the batch back when Anthropic has ended it (the 15-minute check timer), check the
//                             answer, and write at most five ideas through `ai_suggestion_add` (deduped, capped).
//  The model reads counts, costs and shapes and the titles and states of earlier ideas: never a row of the owner's data.
//  Its answer is input: every idea passes `checkedIdea`, names a pattern it was shown, and its key is made from that
//  pattern, never from the model. A failure never loops (a failed week is not tried again by the timer) and never stops
//  anything else: the report and every answer run before and apart from this.
// ─────────────────────────────────────────────────────────────────────────────

type SuggestMakeReply =
  | { ok: true; queued: true; run_id: string; week_start: string }
  | { ok: true; queued: false; skipped: 'not_the_time' | 'already_made' | 'already_queued' | 'nothing_repeats'; week_start: string | null }
  | { ok: false; reason: 'error' | 'off' | 'not_configured' | 'busy' | 'budget' | 'bad_input' | 'failed'; message: string }

type SuggestCheckReply =
  | { ok: true; checked: number; done: number; failed: number; waiting: number }
  | { ok: false; message: string }

// ── Step 1: make ────────────────────────────────────────────────────────────

async function makeWeeklySuggestions(ctx: RunContext): Promise<SuggestMakeReply> {
  const job = SUGGEST_WEEKLY_JOB
  const scheduled = ctx.caller === 'schedule'
  if (!job.callers.includes(ctx.caller)) return { ok: false, reason: 'bad_input', message: `"${job.title}" can't be started from here.` }
  const now = ctx.now()
  // The timer looks at the week that just ended, in the same window as the report (05:00 to 07:00 Monday); the button looks at this week.
  const week = scheduled ? scheduledReportWeek(now)?.start ?? null : osloWeekOf(now).start
  if (!week) return { ok: true, queued: false, skipped: 'not_the_time', week_start: null }
  const madeBy: 'schedule' | 'app' = scheduled ? 'schedule' : 'app'

  const existing = await findRun(ctx.adminDb, ctx.userId, week, madeBy)
  if (existing === undefined) return { ok: false, reason: 'error', message: 'The earlier runs could not be read, so nothing was queued. Try again in a moment.' }
  if (existing?.status === 'queued') return { ok: true, queued: false, skipped: 'already_queued', week_start: week }
  // The timer makes one run a week, a failed one included (no loop); the button may ask again.
  if (existing && scheduled) return { ok: true, queued: false, skipped: 'already_made', week_start: week }

  const stop = async (reason: 'off' | 'not_configured' | 'busy' | 'error' | 'budget', message: string, model: string): Promise<SuggestMakeReply> => {
    // The timer says nothing when AI is off or not set up (the report's own try already said it); only the owner's button leaves a row.
    if (reason !== 'busy' && !scheduled) {
      const row = ledgerRow(ctx, model, job)
      row.outcome = reason
      row.error = cutChars(message, FAILURE_MAX)
      const problem = await writeCall(ctx.adminDb, row)
      if (problem) ctx.report(`a call was not written to the ledger: ${problem}`)
    }
    return { ok: false, reason, message }
  }

  const gate = await readGate(ctx.userDb, job.name, gateScopeOf(ctx))
  if (!gate) return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was queued. Try again in a moment.' }
  const tooMany = rateCapProblem(gate, ctx.caller)
  if (tooMany) return { ok: false, reason: 'busy', message: tooMany }
  const stored = await readSettingRows(ctx.userDb, ctx.userId, job.name)
  if (!stored) return stop('error', 'Your AI settings could not be read, so nothing was queued. Try again in a moment.', job.defaults.model)
  const settings = settingsFor(job, stored.account, stored.job)
  if (!settings.aiEnabled) return stop('off', 'All AI is switched off in Developer → AI → Settings.', settings.model)
  if (!settings.enabled) return stop('off', `"${job.title}" is switched off in Developer → AI → Settings.`, settings.model)
  if (!ctx.provider) return stop('not_configured', 'AI is not set up yet: the server has no API key for it.', settings.model)

  // AI last: the counting is a database function; the model is asked only when something repeats.
  const patterns = await countPatterns(ctx.adminDb, ctx.userId)
  if (!patterns) return { ok: false, reason: 'error', message: 'The ledger could not be counted, so nothing was queued. Try again in a moment.' }
  const earlier = await readEarlierIdeas(ctx.adminDb, ctx.userId)
  if (!earlier) return { ok: false, reason: 'error', message: 'The earlier ideas could not be read, so nothing was queued. Try again in a moment.' }
  const userText = weeklyPrompt(patterns, earlier)
  const factsJson = { patterns } as unknown as Record<string, unknown>

  const runId = existing ? existing.id : ctx.newId()
  const saved = existing
    ? await requeueRun(ctx.adminDb, ctx.userId, existing.id, userText, patterns.length, factsJson, now.toISOString()) ? 'ok' : 'exists'
    : await insertRun(ctx.adminDb, { id: runId, user_id: ctx.userId, week_start: week, made_by: madeBy, sent_text: userText, patterns: patterns.length, facts: factsJson })
  if (saved === 'exists') return { ok: true, queued: false, skipped: 'already_queued', week_start: week }
  if (saved === 'error') return { ok: false, reason: 'error', message: 'The run could not be saved, so nothing was queued. Try again in a moment.' }
  const fail = (message: string) => patchRun(ctx.adminDb, ctx.userId, runId, { status: 'failed', failure: cutChars(message, FAILURE_MAX), finished_at: ctx.now().toISOString() }, true)

  if (patterns.length === 0) {
    // Nothing repeats enough to be an idea: no model call, no cost; the run says so.
    await patchRun(ctx.adminDb, ctx.userId, runId, { status: 'done', added: 0, finished_at: ctx.now().toISOString() }, true)
    return { ok: true, queued: false, skipped: 'nothing_repeats', week_start: week }
  }

  const request = buildRequest(job, settings, userText, settings.thinking)
  const worstCost = worstCostOf(request.model, request.instructions.length + request.userText.length, request.maxOutputTokens, 'batch')
  const reservation = await reserveCall(ctx.adminDb, {
    userId: ctx.userId, job: job.name, caller: ctx.caller, mode: 'batch', provider: ctx.providerName, model: request.model,
    effort: request.effort, instructionsVersion: job.version, worstCostUsd: worstCost,
    budgetUsd: settings.monthlyBudgetUsd, jobBudgetUsd: settings.jobBudgetUsd,
    perMinute: LIMITS.callsPerMinute, perDay: LIMITS.callsPerDay, callerPerDay: callerDailyCap(ctx.caller),
  })
  if (!reservation) {
    await fail('The AI budget could not be checked, so nothing was queued.')
    return { ok: false, reason: 'error', message: 'The AI budget could not be checked, so nothing was queued. Try again in a moment.' }
  }
  if (reservation.kind === 'busy') {
    await fail('Too many AI calls at the moment, so nothing was queued.')
    return { ok: false, reason: 'busy', message: `That is more than ${LIMITS.callsPerMinute} AI calls in a minute, ${LIMITS.callsPerDay} today, or ${callerDailyCap(ctx.caller)} in 24 hours. Wait a moment and try again.` }
  }
  if (reservation.kind === 'budget') {
    const message = reservationBudgetProblem(settings, job.title)
    await fail(message)
    return { ok: false, reason: 'budget', message }
  }
  const callId = reservation.id
  await patchRun(ctx.adminDb, ctx.userId, runId, { call_id: callId }, true)

  const started = Date.now()
  let submitted
  try {
    submitted = await ctx.provider.submitBatch([{ customId: callId, request }], BATCH_REQUEST_MS)
  } catch (error) {
    ctx.report(`the provider part threw: ${errorPlace(error)}`)
    submitted = { ok: false as const, kind: 'unknown' as const, status: null, message: 'The batch could not be queued: the AI call failed unexpectedly.', detail: '', requestId: null, sent: null }
  }
  if (!submitted.ok) {
    const message = hideSecrets(submitted.message, ctx.secrets)
    await fail(message)
    const patch: Partial<CallRow> = {
      outcome: 'error', stop_reason: 'batch_not_queued', error: cutChars(hideSecrets(settings.logText ? `${submitted.message} ${submitted.detail}`.trim() : submitted.message, ctx.secrets), FAILURE_MAX),
      duration_ms: Math.max(0, Date.now() - started),
      ...(MAY_BE_BILLED.includes(submitted.kind) ? {} : { cost_usd: 0 }),
    }
    const problem = await patchCall(ctx.adminDb, ctx.userId, callId, patch)
    if (problem) ctx.report(`a call could not be finished in the ledger (it stays at its reserved cost): ${problem}`)
    return { ok: false, reason: 'failed', message }
  }
  if (!(await patchRun(ctx.adminDb, ctx.userId, runId, { batch_id: submitted.batchId }, true))) {
    ctx.report('the suggestions batch was queued but its id could not be saved: the run will be given up after 26 hours (its worst case stays in the ledger)')
  }
  const logPatch: Partial<CallRow> = {
    effort: request.effort, stop_reason: 'batch_queued', duration_ms: 0,
    ...(settings.logText ? { request: trimForLog({
      model: request.model, effort: request.effort, max_output_tokens: request.maxOutputTokens, instructions_version: job.version,
      instructions: request.instructions, user_text: request.userText, thinking: request.thinking, mode: 'batch',
    }, TEXT_LOG_MAX_BYTES) } : {}),
  }
  const problem = await patchCall(ctx.adminDb, ctx.userId, callId, logPatch)
  if (problem) ctx.report(`a batch's ledger row could not be updated: ${problem}`)
  return { ok: true, queued: true, run_id: runId, week_start: week }
}

// ── Step 2: check ───────────────────────────────────────────────────────────

async function checkSuggestRuns(ctx: RunContext): Promise<SuggestCheckReply> {
  if (!ctx.provider) return { ok: false, message: 'AI is not set up yet: the server has no API key for it.' }
  const now = ctx.now()
  await releaseStaleRunClaims(ctx.adminDb, ctx.userId, new Date(now.getTime() - CLAIM_MS).toISOString())
  const queued = await queuedRuns(ctx.adminDb, ctx.userId)
  if (!queued) return { ok: false, message: 'The suggestion runs could not be read. Try again in a moment.' }
  const tally = { checked: 0, done: 0, failed: 0, waiting: 0 }
  for (const run of queued) {
    if (!(await claimRun(ctx.adminDb, ctx.userId, run.id, run.created_at, now.toISOString()))) continue
    tally.checked += 1
    let outcome: 'done' | 'failed' | 'waiting'
    try {
      outcome = await checkOneRun(ctx, run)
    } catch (error) {
      ctx.report(`a suggestion run check threw: ${errorPlace(error)}`)
      outcome = 'waiting'
    }
    tally[outcome] += 1
    if (outcome === 'waiting') await patchRun(ctx.adminDb, ctx.userId, run.id, { claimed_at: null }, true, run.created_at)
  }
  return { ok: true, ...tally }
}

async function suggestLedgerFinish(ctx: RunContext, run: RunRow, patch: Partial<CallRow>): Promise<void> {
  if (!run.call_id) { ctx.report('a suggestion run has no ledger row to correct'); return }
  const problem = await patchCall(ctx.adminDb, ctx.userId, run.call_id, patch)
  if (problem) ctx.report(`a call could not be finished in the ledger (it stays at its reserved cost): ${problem}`)
}

async function endSuggestRun(ctx: RunContext, run: RunRow, message: string, stopReason: string | null, keepWorstCase: boolean): Promise<void> {
  if (keepWorstCase) await suggestLedgerFinish(ctx, run, { outcome: 'error', stop_reason: stopReason, error: cutChars(message, FAILURE_MAX) })
  await patchRun(ctx.adminDb, ctx.userId, run.id, { status: 'failed', failure: cutChars(message, FAILURE_MAX), finished_at: ctx.now().toISOString(), claimed_at: null }, true, run.created_at)
}

async function checkOneRun(ctx: RunContext, run: RunRow): Promise<'done' | 'failed' | 'waiting'> {
  const provider = ctx.provider
  if (!provider) return 'waiting'
  const age = ctx.now().getTime() - Date.parse(run.created_at)
  const tooOld = Number.isFinite(age) && age > BATCH_GIVE_UP_MS
  const giveUp = async (message: string, stopReason: string): Promise<'failed'> => { await endSuggestRun(ctx, run, message, stopReason, true); return 'failed' }
  if (!run.batch_id) return age > BATCH_NO_ID_MS || tooOld ? giveUp('The batch was never registered, so there is nothing to read.', 'batch_not_registered') : 'waiting'
  const status = await provider.batchStatus(run.batch_id, BATCH_STATUS_MS)
  if (!status.ok) return tooOld ? giveUp('Anthropic could not be asked about the batch for more than a day.', 'batch_unreachable') : 'waiting'
  if (status.status !== 'ended') return tooOld ? giveUp('The batch did not end within a day.', 'batch_expired') : 'waiting'
  const results = await provider.batchResults(run.batch_id, BATCH_REQUEST_MS)
  if (!results.ok) return tooOld ? giveUp('The results could not be read for more than a day.', 'batch_unreachable') : 'waiting'
  const line = results.lines.find(l => l.customId === run.call_id)
  if (!line || !run.call_id) return giveUp('The batch ended without a result for this run.', 'batch_no_result')
  if (line.kind !== 'succeeded') {
    const word = line.kind === 'errored' ? 'failed' : line.kind === 'expired' ? 'expired before it was answered' : 'was cancelled'
    return giveUp(`The batch request ${word}.`, `batch_${line.kind}`)
  }
  const answer: ModelAnswer = line.answer
  const stored = await readSettingRows(ctx.userDb, ctx.userId, SUGGEST_WEEKLY_JOB.name)
  const logText = stored ? settingsFor(SUGGEST_WEEKLY_JOB, stored.account, stored.job).logText : false
  const patterns = storedPatterns(run.facts)
  const failure = answerProblem(answer)
  const read = failure ? null : readWeeklyIdeas(answer.text, patterns)
  const bad = failure ?? (read && !read.ok ? `The model's answer could not be used: ${read.problem}.` : null)
  const price = costOf(answer.usage, answer.servedModel ?? SUGGEST_WEEKLY_JOB.defaults.model, 'batch')
  const real: Partial<CallRow> = {
    served_model: answer.servedModel, request_id: answer.requestId, stop_reason: answer.stopReason,
    input_tokens: answer.usage.inputTokens, cache_read_tokens: answer.usage.cacheReadTokens,
    cache_write_5m_tokens: answer.usage.cacheWrite5mTokens, cache_write_1h_tokens: answer.usage.cacheWrite1hTokens,
    output_tokens: answer.usage.outputTokens, thinking_tokens: answer.usage.thinkingTokens, long_prompt: price.longPrompt,
    cost_usd: price.costUsd, duration_ms: Number.isFinite(age) ? Math.max(0, Math.round(age)) : 0,
    ...(logText ? { response: trimForLog({ text: answer.text, ...(answer.refusal ? { refusal: answer.refusal } : {}) }, TEXT_LOG_MAX_BYTES), thinking: answer.thinking ? trimText(answer.thinking, TEXT_LOG_MAX_BYTES) : null } : {}),
  }
  if (bad || !read || !read.ok) {
    await suggestLedgerFinish(ctx, run, { ...real, outcome: answer.ending === 'refused' ? 'refused' : answer.ending === 'cut_off' ? 'cut_off' : 'invalid', error: cutChars(hideSecrets(bad ?? 'unusable', ctx.secrets), FAILURE_MAX) })
    await endSuggestRun(ctx, run, bad ?? 'The answer could not be used.', null, false)
    return 'failed'
  }
  await suggestLedgerFinish(ctx, run, { ...real, outcome: 'ok', error: null })
  // The ideas: each through the database function (the key from its pattern, a dismissed idea never written, the caps).
  let added = 0
  for (const { pattern, idea } of read.ideas) {
    const result = await addSuggestion(ctx.adminDb, ctx.userId, idea, await patternKey(pattern), 'weekly', savingOf(pattern), pattern.firstCallId)
    if (result === 'added') added += 1
    else if (result === 'error') ctx.report('an idea could not be saved')
  }
  if (!(await patchRun(ctx.adminDb, ctx.userId, run.id, { status: 'done', added: Math.min(added, 5), failure: null, finished_at: ctx.now().toISOString(), claimed_at: null }, true, run.created_at))) {
    ctx.report('a finished suggestion run could not be saved (it was made again meanwhile, or the write failed)')
    return 'waiting'
  }
  return 'done'
}

// ═══ supabase/claude-src/chat-store.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · Ask AI, the stored chats (migration 197)
//
//  The function's whole use of the three chat tables, with the service-role client: that client has no row level
//  security, so EVERY query names the user id main.ts verified (and a message or a proposal is also tied to its
//  conversation by a composite foreign key in the database). Nothing here reads a user id from a request.
//
//  A chat is only added to: this part inserts messages and never updates or deletes one (the database refuses both).
//  A read that fails answers null / an error word and the caller sends nothing.
// ─────────────────────────────────────────────────────────────────────────────

interface ConversationRow {
  id: string
  user_id: string
  title: string | null
  model: string
  effort: 'low' | 'medium' | 'high'
  thinking: 'adaptive' | 'off'
  tools_hash: string
  system_hash: string
  tool_names: string[]
  status: 'open' | 'full' | 'closed'
  message_count: number
  last_prompt_tokens: number
  cost_usd: number
  /** Set when the owner deleted the chat (the Undo window): such a chat is treated as not there. */
  deleted_at: string | null
  /** Which kind of chat it was started as (frozen): its instructions and tool set follow from it. */
  mode: ChatMode
  /** The owner's own instructions as they were when the chat started (frozen, cleaned). */
  owner_instructions: string
}

interface StoredMessage {
  seq: number
  role: 'user' | 'assistant'
  content: Block[]
  digest: string
  call_id: string | null
  meta: Record<string, unknown>
  created_at: string
}

interface ProposalRow {
  id: string
  user_id: string
  conversation_id: string
  tool_use_id: string
  tool: 'add_task' | 'log_food'
  args: unknown
  summary: string
  status: 'pending' | 'confirmed' | 'cancelled' | 'failed'
  created_at: string
  expires_at: string
  decided_at: string | null
  result_id: string | null
}

const STORE_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const STORE_PAGE = 500
const MAX_MESSAGES = 600

const isUuid = (value: unknown): value is string => typeof value === 'string' && STORE_UUID.test(value)

const CONVERSATION_COLUMNS = 'id, user_id, title, model, effort, thinking, tools_hash, system_hash, tool_names, status, message_count, last_prompt_tokens, cost_usd, deleted_at, mode, owner_instructions'

function conversationOf(row: unknown): ConversationRow | null {
  const effort = ownValue(row, 'effort')
  const thinking = ownValue(row, 'thinking')
  const status = ownValue(row, 'status')
  const names = ownValue(row, 'tool_names')
  const id = ownValue(row, 'id')
  const userId = ownValue(row, 'user_id')
  if (!isUuid(id) || !isUuid(userId) || typeof ownValue(row, 'model') !== 'string') return null
  if (effort !== 'low' && effort !== 'medium' && effort !== 'high') return null
  if (thinking !== 'adaptive' && thinking !== 'off') return null
  if (status !== 'open' && status !== 'full' && status !== 'closed') return null
  if (!Array.isArray(names) || names.some(n => typeof n !== 'string')) return null
  const mode = ownValue(row, 'mode')
  if (mode !== 'chat' && mode !== 'coach') return null
  const frozen = ownValue(row, 'owner_instructions')
  if (typeof frozen !== 'string') return null
  const num = (v: unknown) => (typeof v === 'number' ? v : Number(v))
  return {
    id, user_id: userId, title: typeof ownValue(row, 'title') === 'string' ? ownValue(row, 'title') as string : null,
    model: ownValue(row, 'model') as string, effort, thinking,
    tools_hash: String(ownValue(row, 'tools_hash')), system_hash: String(ownValue(row, 'system_hash')),
    tool_names: names as string[], status, message_count: num(ownValue(row, 'message_count')) || 0,
    last_prompt_tokens: num(ownValue(row, 'last_prompt_tokens')) || 0, cost_usd: num(ownValue(row, 'cost_usd')) || 0,
    deleted_at: typeof ownValue(row, 'deleted_at') === 'string' ? ownValue(row, 'deleted_at') as string : null,
    mode, owner_instructions: frozen,
  }
}

async function createConversation(admin: Db, row: Omit<ConversationRow, 'message_count' | 'last_prompt_tokens' | 'cost_usd' | 'status' | 'deleted_at'>): Promise<string | null> {
  try {
    const { error } = await admin.from('ai_conversations').insert({ ...row })
    return error ? `database error ${error.code ?? 'without a code'}` : null
  } catch { return 'the database could not be reached' }
}

/** One conversation of this user, or null (also for another user's id: the query names the user). `error`: it could not be read. */
async function readConversation(admin: Db, userId: string, id: string): Promise<{ conversation: ConversationRow | null; error: boolean }> {
  try {
    const { data, error } = await admin.from('ai_conversations').select(CONVERSATION_COLUMNS).eq('id', id).eq('user_id', userId).maybeSingle()
    if (error) return { conversation: null, error: true }
    return { conversation: data ? conversationOf(data) : null, error: false }
  } catch { return { conversation: null, error: true } }
}

/** Deletes a chat softly (the Undo window) or brings it back. True when a row of this user changed. */
async function setConversationDeleted(admin: Db, userId: string, id: string, deletedAt: string | null): Promise<boolean> {
  try {
    const { data, error } = await admin.from('ai_conversations').update({ deleted_at: deletedAt }).eq('id', id).eq('user_id', userId).select('id')
    return !error && Array.isArray(data) && data.length === 1
  } catch { return false }
}

async function updateConversation(admin: Db, userId: string, id: string, patch: Record<string, unknown>): Promise<string | null> {
  try {
    const { error } = await admin.from('ai_conversations').update({ ...patch, updated_at: new Date().toISOString() }).eq('id', id).eq('user_id', userId)
    return error ? `database error ${error.code ?? 'without a code'}` : null
  } catch { return 'the database could not be reached' }
}

function messageOf(row: unknown): StoredMessage | null {
  const seq = ownValue(row, 'seq')
  const role = ownValue(row, 'role')
  const content = ownValue(row, 'content')
  const digest = ownValue(row, 'digest')
  if (typeof seq !== 'number' || (role !== 'user' && role !== 'assistant') || !Array.isArray(content) || typeof digest !== 'string') return null
  const meta = ownValue(row, 'meta')
  const callId = ownValue(row, 'call_id')
  return {
    seq, role, content: content as Block[], digest, call_id: typeof callId === 'string' ? callId : null,
    meta: meta !== null && typeof meta === 'object' && !Array.isArray(meta) ? meta as Record<string, unknown> : {},
    created_at: String(ownValue(row, 'created_at') ?? ''),
  }
}

/** A conversation's messages in order, or null when they cannot be read or are too many. */
async function readMessages(admin: Db, userId: string, conversationId: string): Promise<StoredMessage[] | null> {
  try {
    const out: StoredMessage[] = []
    for (let page = 0; out.length < MAX_MESSAGES; page++) {
      const { data, error } = await admin.from('ai_messages').select('seq, role, content, digest, call_id, meta, created_at')
        .eq('conversation_id', conversationId).eq('user_id', userId).order('seq', { ascending: true }).range(page * STORE_PAGE, page * STORE_PAGE + STORE_PAGE - 1)
      if (error || !Array.isArray(data)) return null
      for (const row of data) {
        const message = messageOf(row)
        if (!message) return null
        out.push(message)
      }
      if (data.length < STORE_PAGE) return out
    }
    return null
  } catch { return null }
}

/**
 * Checks the history before it is replayed: numbers 1, 2, 3 … with none missing, roles that alternate sensibly, and the
 * hash chain. A history that fails is never sent: the chat is refused as changed.
 */
async function historyIsIntact(messages: readonly StoredMessage[]): Promise<boolean> {
  let previous: string | null = null
  for (let i = 0; i < messages.length; i++) {
    const m = messages[i]
    if (m.seq !== i + 1) return false
    if (m.digest !== await messageDigest(previous, m.role, m.content)) return false
    previous = m.digest
  }
  return true
}

/** The history as the model gets it. */
function asChatMessages(messages: readonly StoredMessage[]): ChatMessage[] {
  return messages.map(m => ({ role: m.role, content: m.content }))
}

/** Adds one message. `conflict`: another request took that number (two answers at once). */
async function appendMessage(
  admin: Db, row: { conversation_id: string; user_id: string; seq: number; role: 'user' | 'assistant'; content: Block[]; digest: string; call_id: string | null; meta: Record<string, unknown> },
): Promise<'ok' | 'conflict' | 'error'> {
  try {
    const { error } = await admin.from('ai_messages').insert({ ...row })
    if (!error) return 'ok'
    return error.code === '23505' ? 'conflict' : 'error'
  } catch { return 'error' }
}

function proposalOf(row: unknown): ProposalRow | null {
  const id = ownValue(row, 'id')
  const tool = ownValue(row, 'tool')
  const status = ownValue(row, 'status')
  if (!isUuid(id) || !isUuid(ownValue(row, 'user_id')) || !isUuid(ownValue(row, 'conversation_id'))) return null
  if (tool !== 'add_task' && tool !== 'log_food') return null
  if (status !== 'pending' && status !== 'confirmed' && status !== 'cancelled' && status !== 'failed') return null
  const text = (key: string) => String(ownValue(row, key) ?? '')
  const resultId = ownValue(row, 'result_id')
  return {
    id, user_id: ownValue(row, 'user_id') as string, conversation_id: ownValue(row, 'conversation_id') as string,
    tool_use_id: text('tool_use_id'), tool, args: ownValue(row, 'args'), summary: text('summary'), status,
    created_at: text('created_at'), expires_at: text('expires_at'),
    decided_at: ownValue(row, 'decided_at') ? text('decided_at') : null, result_id: isUuid(resultId) ? resultId : null,
  }
}

const PROPOSAL_COLUMNS = 'id, user_id, conversation_id, tool_use_id, tool, args, summary, status, created_at, expires_at, decided_at, result_id'

async function insertProposal(
  admin: Db, row: { id: string; user_id: string; conversation_id: string; tool_use_id: string; tool: 'add_task' | 'log_food'; args: Record<string, unknown>; summary: string; expires_at: string },
): Promise<boolean> {
  try {
    const { error } = await admin.from('ai_chat_proposals').insert({ ...row })
    return !error
  } catch { return false }
}

/** One proposal of this user by its id, or null. `error`: it could not be read. */
async function readProposal(admin: Db, userId: string, id: string): Promise<{ proposal: ProposalRow | null; error: boolean }> {
  try {
    const { data, error } = await admin.from('ai_chat_proposals').select(PROPOSAL_COLUMNS).eq('id', id).eq('user_id', userId).maybeSingle()
    if (error) return { proposal: null, error: true }
    return { proposal: data ? proposalOf(data) : null, error: false }
  } catch { return { proposal: null, error: true } }
}

/**
 * Decides a pending proposal once: the update only matches a row that is still pending, for this user, so two taps (or a
 * tap and a replay) cannot both win. True when this call is the one that decided it.
 */
async function decideProposal(admin: Db, userId: string, id: string, status: 'confirmed' | 'cancelled' | 'failed', nowIso: string, args?: Record<string, unknown>): Promise<boolean> {
  try {
    // `args`: the owner's edits (a changed title or date), already checked, kept on the row so it says what was written.
    const { data, error } = await admin.from('ai_chat_proposals').update({ status, decided_at: nowIso, ...(args ? { args } : {}) })
      .eq('id', id).eq('user_id', userId).eq('status', 'pending').select('id')
    return !error && Array.isArray(data) && data.length === 1
  } catch { return false }
}

/** A confirmed proposal whose write failed is marked failed (only a confirmed one with no result: never a pending or a finished one). */
async function markProposalFailed(admin: Db, userId: string, id: string): Promise<void> {
  try {
    await admin.from('ai_chat_proposals').update({ status: 'failed' }).eq('id', id).eq('user_id', userId).eq('status', 'confirmed').is('result_id', null)
  } catch { /* the card then shows confirmed: the row is not there, and the app says so */ }
}

async function setProposalResult(admin: Db, userId: string, id: string, resultId: string): Promise<void> {
  try {
    await admin.from('ai_chat_proposals').update({ result_id: resultId }).eq('id', id).eq('user_id', userId)
  } catch { /* the row was written; only the card's Open link is missing */ }
}

/** A conversation's proposals decided after `sinceIso`: the model is told about them in its next live-context block. */
async function decidedProposalsSince(admin: Db, userId: string, conversationId: string, sinceIso: string): Promise<ProposalRow[]> {
  try {
    const { data, error } = await admin.from('ai_chat_proposals').select(PROPOSAL_COLUMNS)
      .eq('conversation_id', conversationId).eq('user_id', userId).gte('decided_at', sinceIso).order('decided_at', { ascending: true }).limit(20)
    if (error || !Array.isArray(data)) return []
    return data.map(proposalOf).filter((p): p is ProposalRow => p !== null)
  } catch { return [] }
}

/** Whether a row the owner's own client can see exists with this id: the citation check (a citation only links to the owner's own rows). */
async function ownRowTitle(db: Db, userId: string, kind: 'task' | 'diary', id: string): Promise<{ title: string; day: string | null } | null> {
  try {
    if (kind === 'task') {
      const { data, error } = await db.from('tasks').select('title, due_date').eq('id', id).eq('user_id', userId).maybeSingle()
      return error || !data ? null : { title: String(ownValue(data, 'title') ?? ''), day: typeof ownValue(data, 'due_date') === 'string' ? ownValue(data, 'due_date') as string : null }
    }
    const { data, error } = await db.from('diary_entries').select('day').eq('id', id).eq('user_id', userId).maybeSingle()
    const day = ownValue(data, 'day')
    return error || typeof day !== 'string' ? null : { title: 'Diary', day }
  } catch { return null }
}

// ── What the owner chose (migration 198) ────────────────────────────────────

const PG_MISSING = new Set(['42P01', 'PGRST205', '42703', 'PGRST204'])

/**
 * The owner's own controls: each tool's mode (after the code's checks: `toolModes`) and the instructions (cleaned, cut).
 * Both are written by the browser, so both are input.
 * - The tool rows: ANY error reading them means "could not read": nothing is sent. There is no fallback to the defaults
 *   (a tool the owner switched off must never come back because a read failed; migration 198 deploys before the function).
 *   Only the code's own tool names are asked for.
 * - The instructions: a database without the column has none (remove that fallback once 198 has run everywhere).
 * Null when they could not be read.
 */
async function readChatControls(db: Db, userId: string): Promise<{ modes: Record<string, ToolMode>; instructions: string } | null> {
  try {
    const [tools, account] = await Promise.all([
      db.from('ai_tool_settings').select('tool, mode').eq('user_id', userId).in('tool', [...ALL_TOOL_ORDER]).limit(50),
      db.from('ai_settings').select('chat_instructions').eq('user_id', userId).maybeSingle(),
    ])
    if (tools.error || !Array.isArray(tools.data)) return null
    if (account.error && !PG_MISSING.has(String(account.error.code))) return null
    return {
      modes: toolModes(tools.data),
      instructions: account.error ? '' : cleanOwnerInstructions(ownValue(account.data, 'chat_instructions')),
    }
  } catch { return null }
}

// ═══ supabase/claude-src/chat-loop.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · Ask AI, the loop
//
//  One answer of the chat, from the person's message to the finished reply, with OUR OWN loop (the owner's decision,
//  20.11.2026: full control over tool execution, logging, error handling and the database):
//
//    1. the walls, in order: the caller (the app only), the rate caps, the input, the settings, the switches, the key;
//    2. the chat: a new one is started with the tools that are not off (frozen with the instructions' hash), an old one
//       is loaded, its history checked (numbers, hash chain) and refused if it changed, or if the code's tools or
//       instructions are no longer the ones it began with, or if it is full (the wall at 90 000 prompt tokens);
//    3. each round: the worst case is RESERVED against the budget, the request is sent (streamed), the answer is stored
//       exactly as it came, and the ledger row of the round (same run_id, the next step) gets the real numbers;
//    4. when the model asks for tools, they run side by side as the owner, and ALL their results go back in ONE message
//       with the results first; a failure is an `is_error` result that says what to try;
//    5. at most CHAT_LIMITS.maxRounds rounds; the last may not call a tool, so an answer always ends in words;
//    6. the citations the model made are checked against what the tools really returned and against the owner's own rows.
//
//  The writes the model proposes are rows in ai_chat_proposals until the owner taps Confirm (`decideChatProposal`).
//  This part never imports the SDK: it talks to the provider through the neutral ChatRequest.
// ─────────────────────────────────────────────────────────────────────────────

/** The only events the app ever gets from a chat: our own small ones. */
type ChatEvent =
  | { event: 'start'; conversation_id: string; is_new: boolean }
  | { event: 'text'; t: string }
  | { event: 'step'; name: string; label: string }
  | { event: 'retract' }
  /** The tool call as the code understood it (checked inputs), after it ran: shown on its step. */
  | { event: 'detail'; name: string; input: Record<string, string | number>; ok: boolean }
  | { event: 'proposal'; id: string; tool: string; summary: string; expires_at: string }
  | { event: 'done'; conversation_id: string; text: string; citations: ChatCitation[]; proposals: ChatProposalCard[]; rounds: number; cost_usd: number; wall: boolean; run_id: string; ending: 'complete' | 'cut_off'; prompt_tokens: number; thinking: string; suggestion: ChatSuggestionNote | null }
  | { event: 'error'; reason: ChatReason; message: string; conversation_id?: string; cost_usd?: number; run_id?: string }

type ChatReason = 'bad_input' | 'busy' | 'off' | 'not_configured' | 'budget' | 'wall' | 'stale' | 'changed' | 'not_found' | 'declined' | 'timeout' | 'conflict' | 'error'

interface ChatCitation { kind: 'task' | 'diary'; id: string; title: string; day: string | null }
/** An idea this answer recorded in the Suggestions list: only its kind (the text is shown in the list, never here). */
interface ChatSuggestionNote { kind: SuggestKind }
interface ChatProposalCard { id: string; tool: string; summary: string; expires_at: string }

type ChatResult = Extract<ChatEvent, { event: 'done' }> | Extract<ChatEvent, { event: 'error' }>

const STEP_LABELS: Record<string, string> = {
  get_day_plan: "Looking at the day's plan",
  get_week_figures: "Looking up the week's figures",
  get_food_day: "Looking up the day's food",
  find_text: 'Searching your tasks and diary',
  ask_database: 'Asking the database',
  propose_add_task: 'Preparing a task for you to confirm',
  propose_log_food: 'Preparing a food line for you to confirm',
  get_training_week: "Looking at the week's training",
  get_health_trends: "Looking at the week's health figures",
  get_pt_verdicts: "Reading the coach's saved verdicts",
  note_shortcut: 'Noting an idea for the Suggestions list',
}

const TOOL_USE_ID = /^[A-Za-z0-9_-]{1,100}$/
const NO_ANSWER = 'The model gave no answer text.'

/** A message from the person: control characters out (a new line stays), trimmed, 1 to 4000 characters, or null. */
function cleanChatText(value: unknown): string | null {
  if (typeof value !== 'string') return null
  // eslint-disable-next-line no-control-regex -- control characters are exactly what is taken out
  const text = value.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').trim()
  const length = [...text].length
  return length >= 1 && length <= CHAT_LIMITS.textMax ? text : null
}

const errorEvent = (reason: ChatReason, message: string, conversationId?: string, spent?: { cost: number; runId: string }): Extract<ChatEvent, { event: 'error' }> =>
  ({ event: 'error', reason, message, ...(conversationId ? { conversation_id: conversationId } : {}), ...(spent && spent.cost > 0 ? { cost_usd: Math.round(spent.cost * 1_000_000) / 1_000_000, run_id: spent.runId } : {}) })

/** The shape of one tool call for the ledger (and phase 4c's suggestions): its name, which fields it filled, how much came back. Never a value. */
interface ToolShape { name: string; fields: string[]; ok: boolean; rows: number | null; bytes: number; ms: number; fingerprint?: string }

/** Every `search_result` source a tool really returned, over the whole history: what a citation may point to. */
function knownSources(messages: readonly { content: Block[] }[]): Set<string> {
  const out = new Set<string>()
  for (const m of messages) {
    for (const block of m.content) {
      if (block.type !== 'tool_result' || !Array.isArray(block.content)) continue
      for (const inner of block.content as Block[]) if (inner.type === 'search_result' && typeof inner.source === 'string') out.add(inner.source)
    }
  }
  return out
}

/**
 * The citations an answer may show: each must be a source a tool returned in this chat (so the model cannot invent a
 * link), must have the exact shape of ours, and must be a row the owner's own client reads (a source is input too).
 * The title shown is the row's own, never the model's.
 */
async function checkedCitations(ctx: RunContext, content: readonly Block[], known: ReadonlySet<string>): Promise<ChatCitation[]> {
  const out: ChatCitation[] = []
  const seen = new Set<string>()
  for (const block of content) {
    if (block.type !== 'text' || !Array.isArray(block.citations)) continue
    for (const citation of block.citations as Block[]) {
      const source = citation.type === 'search_result_location' ? citation.source : null
      if (typeof source !== 'string' || seen.has(source) || !known.has(source) || out.length >= 10) continue
      const match = SOURCE_PATTERN.exec(source)
      if (!match) continue
      seen.add(source)
      const row = await ownRowTitle(ctx.userDb, ctx.userId, match[1] as 'task' | 'diary', match[2])
      if (row) out.push({ kind: match[1] as 'task' | 'diary', id: match[2], title: row.title.slice(0, 100), day: row.day })
    }
  }
  return out
}

/** The text blocks of an answer, joined. */
const textOf = (content: readonly Block[]): string => content.filter(b => b.type === 'text' && typeof b.text === 'string').map(b => b.text as string).join('')

/** What a tool result block holds for one finished tool call. */
function resultBlock(toolUseId: string, output: ToolOutput): Block {
  if (!output.ok) return { type: 'tool_result', tool_use_id: toolUseId, content: output.message, is_error: true }
  return { type: 'tool_result', tool_use_id: toolUseId, content: output.blocks && output.blocks.length ? output.blocks : output.text }
}

async function withTimeout<T>(run: Promise<T>, ms: number, onTimeout: T): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const late = new Promise<T>(resolve => { timer = setTimeout(() => resolve(onTimeout), ms) })
  try { return await Promise.race([run, late]) } finally { if (timer) clearTimeout(timer) }
}

/** What the system and the tools of a chat are, hashed: a chat is continued only with the very same ones. */
async function chatHashes(tools: readonly ChatTool[], system: string, ownerBlock: string): Promise<{ tools: string; system: string }> {
  return { tools: await sha256Hex(canonicalJson(tools)), system: await sha256Hex(`${system}\n---\n${ownerBlock}`) }
}

/** The photos of a message list: image blocks. */
const imageBlocksOf = (messages: readonly { content: Block[] }[]): number => messages.reduce((n, m) => n + m.content.filter(b => b.type === 'image').length, 0)

/** The prompt's size in characters with each photo's base64 left out (a photo costs tokens by its pixels, never by its text): the reservation adds the photos' worst case itself. */
const promptChars = (messages: readonly ChatMessage[]): number =>
  // Only the `data` of a photo's source ({ type: 'base64', media_type, data }) is left out: a `data` anywhere else (a tool result, the owner's words) still counts.
  JSON.stringify(messages, function (this: unknown, key, value) {
    const parent = this as Record<string, unknown> | null
    return key === 'data' && typeof value === 'string' && parent !== null && parent.type === 'base64' && typeof parent.media_type === 'string' ? '' : value
  }).length

/** Runs one answer. `emit` gets the events as they happen (the stream); the return value is the final one. */
async function runChat(ctx: RunContext, input: unknown, emit: (event: ChatEvent) => void, signal?: AbortSignal): Promise<ChatResult> {
  const result = await chatAnswer(ctx, input, emit, signal)
  emit(result)
  return result
}

async function chatAnswer(ctx: RunContext, input: unknown, emit: (event: ChatEvent) => void, signal?: AbortSignal): Promise<ChatResult> {
  const job = CHAT_JOB
  const started = Date.now()
  // 1 · The walls. The chat is the app's own: a device cannot start it.
  if (ctx.caller !== 'app' || ctx.readAs !== 'owner') return errorEvent('bad_input', 'Ask AI can only be started from the app.')
  const gate = await readGate(ctx.userDb, job.name, gateScopeOf(ctx))
  if (!gate) {
    ctx.report('the usage could not be read, so nothing was sent')
    return errorEvent('error', 'The AI usage could not be read, so nothing was sent. Try again in a moment.')
  }
  const tooMany = rateCapProblem(gate, ctx.caller)
  if (tooMany) return errorEvent('busy', tooMany)

  const text = cleanChatText(ownValue(input, 'text'))
  if (text === null) return errorEvent('bad_input', `Write a message of 1 to ${CHAT_LIMITS.textMax} characters.`)
  const askedId = ownValue(input, 'conversation_id')
  if (askedId !== null && askedId !== undefined && !isUuid(askedId)) return errorEvent('bad_input', 'That is not a chat this app knows.')
  // A new chat is the everyday one or the Training coach's; a chat that exists keeps the kind it started as.
  const askedMode = ownValue(input, 'mode')
  if (askedMode !== undefined && askedMode !== null && askedMode !== 'chat' && askedMode !== 'coach') return errorEvent('bad_input', 'That kind of chat does not exist.')
  // Photos: each is checked from its own bytes (type, header, size) like every photo; the count is checked again against the whole chat below.
  const rawImages = ownValue(input, 'images')
  if (rawImages !== undefined && rawImages !== null && !Array.isArray(rawImages)) return errorEvent('bad_input', 'The photos must be a list.')
  if (Array.isArray(rawImages) && rawImages.length > CHAT_LIMITS.imagesPerMessage) return errorEvent('bad_input', `At most ${CHAT_LIMITS.imagesPerMessage} photos in one message.`)
  const newImages: { block: Block; tokens: number }[] = []
  for (const raw of Array.isArray(rawImages) ? rawImages : []) {
    const checked = checkedImage(raw, CHAT_LIMITS.imageBase64Max)
    if (!checked.ok) return errorEvent('bad_input', checked.problem)
    newImages.push({ block: { type: 'image', source: { type: 'base64', media_type: checked.image.mediaType, data: checked.image.base64 } }, tokens: Math.min(checked.tokens, CHAT_LIMITS.imageTokensWorst) })
  }

  const stored = await readSettingRows(ctx.userDb, ctx.userId, job.name)
  if (!stored) return errorEvent('error', 'Your AI settings could not be read, so nothing was sent. Try again in a moment.')
  const settings = settingsFor(job, stored.account, stored.job)
  if (!settings.aiEnabled) return errorEvent('off', 'All AI is switched off in Developer → AI → Settings.')
  if (!settings.enabled) return errorEvent('off', `"${job.title}" is switched off in Developer → AI → Settings.`)
  const provider = ctx.provider
  if (!provider) return errorEvent('not_configured', 'AI is not set up yet: the server has no API key for it.')

  // 2 · The chat. What the owner chose (each tool's mode, their own instructions) is read now, as input: the modes are the
  //     wall for every round, the instructions are copied into a NEW chat only.
  const controls = await readChatControls(ctx.userDb, ctx.userId)
  if (!controls) return errorEvent('error', 'Your Ask AI settings could not be read, so nothing was sent. Try again in a moment.')
  const modes = controls.modes
  let conversation: ConversationRow | null = null
  let history: StoredMessage[] = []
  if (typeof askedId === 'string') {
    const found = await readConversation(ctx.adminDb, ctx.userId, askedId)
    if (found.error) return errorEvent('error', 'The chat could not be read, so nothing was sent. Try again in a moment.')
    if (!found.conversation || found.conversation.deleted_at) return errorEvent('not_found', 'That chat was not found. Start a new one.')
    conversation = found.conversation
    if (conversation.status !== 'open') return errorEvent('wall', 'This chat is full. Start a new chat: it keeps working at its best when it is short.', conversation.id)
    if (!MODELS.some(m => m.id === conversation?.model)) return errorEvent('changed', 'This chat uses a model this app no longer offers. Start a new chat.', conversation.id)
    const messages = await readMessages(ctx.adminDb, ctx.userId, conversation.id)
    if (!messages) return errorEvent('error', 'The chat could not be read, so nothing was sent. Try again in a moment.')
    // The history is replayed byte for byte, so it is checked first: a changed or damaged history is never sent.
    if (!(await historyIsIntact(messages))) {
      ctx.report('a chat history failed its check and was not sent')
      return errorEvent('changed', "This chat's saved history does not match what was stored, so it was not sent. Start a new chat.", conversation.id)
    }
    history = messages
  }
  const chatMode: ChatMode = conversation ? conversation.mode : askedMode === 'coach' ? 'coach' : 'chat'
  const toolNames = conversation ? conversation.tool_names : toolsForNewChat(modes, chatMode)
  // A chat that names a tool this code no longer has cannot be replayed with the same tool list.
  if (conversation && toolNames.some(n => !KNOWN_TOOL_NAMES.includes(n))) return errorEvent('stale', 'This chat was started before an update changed the assistant. Start a new chat.', conversation.id)
  const tools = chatToolsNamed(toolNames)
  // The owner's instructions are frozen into the chat when it starts (a second, cached system block); later changes reach new chats only.
  const frozenInstructions = conversation ? cleanOwnerInstructions(conversation.owner_instructions) : controls.instructions
  const ownerInstructions = ownerInstructionsBlock(frozenInstructions)
  const system = systemFor(chatMode)
  const hashes = await chatHashes(tools, system, ownerInstructions)
  if (conversation && (conversation.tools_hash !== hashes.tools || conversation.system_hash !== hashes.system)) {
    return errorEvent('stale', 'This chat was started before an update changed the assistant. Start a new chat.', conversation.id)
  }
  const model = conversation ? conversation.model : settings.model
  const effort = conversation ? conversation.effort : settings.effort
  const thinking = conversation ? conversation.thinking : settings.thinking
  const maxOutputTokens = Math.max(CHAT_LIMITS.minOutputTokens, settings.maxOutputTokens)
  if (newImages.length && imageBlocksOf(history) + newImages.length > CHAT_LIMITS.imagesPerChat) {
    return errorEvent('bad_input', `A chat holds at most ${CHAT_LIMITS.imagesPerChat} photos (each stays in the chat). Start a new chat to send more.`, conversation?.id)
  }
  const conversationId = conversation ? conversation.id : ctx.newId()

  // The new message: results of an interrupted tool call first (when the last answer never got its results), then the
  // app's own notices (the date, what happened to earlier proposals), each in its own block, then the person's words.
  const now = ctx.now()
  const last = history[history.length - 1]
  const blocks: Block[] = []
  if (last && last.role === 'assistant') {
    for (const b of last.content) {
      if (b.type === 'tool_use' && typeof b.id === 'string') {
        blocks.push({ type: 'tool_result', tool_use_id: b.id, content: 'This tool call was interrupted before it finished. Call it again if it is still needed.', is_error: true })
      }
    }
  }
  const liveAt = [...history].reverse().find(m => typeof m.meta.live_at === 'string')?.meta.live_at as string | undefined
  const withDate = needsLiveContext(liveAt ?? null, now)
  if (withDate) blocks.push({ type: 'text', text: liveContextText(now) })
  if (conversation && last) {
    const decided = await decidedProposalsSince(ctx.adminDb, ctx.userId, conversation.id, last.created_at)
    if (decided.length) {
      // Only the kind of proposal and what happened: the owner's words (a title they may have edited) never go into this block.
      blocks.push({ type: 'text', text: `<app_updates>${decided.map(p => `The proposal to ${p.tool === 'add_task' ? 'add a task' : 'log a food line'} was ${p.status === 'confirmed' ? 'confirmed by the person and saved' : p.status === 'cancelled' ? 'cancelled by the person (not saved)' : 'confirmed, but saving it failed (not saved)'}.`).join(' ')} This note comes from the app, not from the person.</app_updates>` })
    }
  }
  // Photos come before the words (Anthropic's advice), each its own block; the person's words are the last block.
  for (const image of newImages) blocks.push(image.block)
  blocks.push({ type: 'text', text })
  const newMessage: ChatMessage = { role: 'user', content: blocks }
  const wire: ChatMessage[] = [...asChatMessages(history), newMessage]
  const baseRequest = (messages: ChatMessage[], noTools: boolean, timeoutMs: number, clocks?: { firstEventTimeoutMs: number; idleTimeoutMs: number }): ChatRequest => ({
    model, maxOutputTokens, effort, thinking, system, ownerInstructions, tools, noTools, messages,
    previousMessageId: typeof history.filter(m => m.role === 'assistant').pop()?.meta.message_id === 'string' ? history.filter(m => m.role === 'assistant').pop()?.meta.message_id as string : null,
    contextEditing: { ...CHAT_LIMITS.contextEditing }, timeoutMs, ...(clocks ?? {}), signal,
  })

  // The wall: the last prompt's size plus the new words is an estimate; near the line the provider counts it exactly (free).
  if (conversation) {
    let estimate = conversation.last_prompt_tokens + Math.ceil(text.length / 3) + 200 + newImages.reduce((n, i) => n + i.tokens, 0)
    if (estimate >= CHAT_LIMITS.preciseCountFromTokens) {
      const counted = await provider.countChat(baseRequest(wire, false, 20_000))
      if (counted.ok) estimate = counted.inputTokens
    }
    if (estimate >= CHAT_LIMITS.wallTokens) {
      await updateConversation(ctx.adminDb, ctx.userId, conversation.id, { status: 'full' })
      return errorEvent('wall', 'This chat is full. Start a new chat: it keeps working at its best when it is short.', conversation.id)
    }
  }

  // 3 · The rounds.
  const runId = ctx.newId()
  const toolsRun: ToolShape[] = []
  const proposals: ChatProposalCard[] = []
  let suggestion: ChatSuggestionNote | null = null
  let notesTried = 0
  const answerMessages: { content: Block[] }[] = []
  let seq = history.length
  let previousDigest: string | null = last ? last.digest : null
  let previousMessageId = baseRequest(wire, false, 0).previousMessageId
  let costTotal = 0
  let streamed = false
  let lastPrompt = conversation ? conversation.last_prompt_tokens : 0
  let createdNow = false
  let forceNoTools = false
  let thinkingSummary = ''
  let endedWith: { text: string; ending: 'complete' | 'cut_off' } | null = null
  let finalCitations: ChatCitation[] = []
  const messages: ChatMessage[] = [...wire]
  let pendingUser: { content: Block[]; meta: Record<string, unknown> } | null = { content: blocks, meta: withDate ? { live_at: now.toISOString() } : {} }
  const known = knownSources(history)

  /** Adds one message to the stored chat. */
  const store = async (role: 'user' | 'assistant', content: Block[], callId: string | null, meta: Record<string, unknown>): Promise<'ok' | 'conflict' | 'error'> => {
    const digest = await messageDigest(previousDigest, role, content)
    const result = await appendMessage(ctx.adminDb, { conversation_id: conversationId, user_id: ctx.userId, seq: seq + 1, role, content, digest, call_id: callId, meta })
    if (result === 'ok') { seq += 1; previousDigest = digest }
    return result
  }
  const fail = (reason: ChatReason, message: string): ChatResult => {
    if (streamed) emit({ event: 'retract' })
    return errorEvent(reason, hideSecrets(message, ctx.secrets), createdNow || conversation ? conversationId : undefined, { cost: costTotal, runId })
  }

  for (let round = 1; round <= CHAT_LIMITS.maxRounds; round++) {
    if (signal?.aborted) return fail('error', 'The request was cancelled.')
    const remaining = CHAT_LIMITS.answerDeadlineMs - (Date.now() - started)
    if (remaining < 8000) return fail('timeout', 'The answer took too long and was stopped. Try a narrower question.')
    const request = baseRequest(messages, round === CHAT_LIMITS.maxRounds || forceNoTools, remaining, { firstEventTimeoutMs: Math.min(CHAT_LIMITS.firstEventMs, remaining), idleTimeoutMs: Math.min(CHAT_LIMITS.idleMs, remaining) })
    request.previousMessageId = previousMessageId

    // The reservation of this round: its worst case is held against the budget before anything is sent.
    const row: CallRow = newRow(ctx, job)
    row.run_id = runId
    row.step = round
    row.model = model
    row.effort = effort
    const worstCost = worstCostOf(model, system.length + ownerInstructions.length + JSON.stringify(tools).length + promptChars(messages), maxOutputTokens, 'live', { imageTokens: imageBlocksOf(messages) * CHAT_LIMITS.imageTokensWorst })
    const reservation = await reserveCall(ctx.adminDb, {
      userId: ctx.userId, job: job.name, caller: ctx.caller, mode: row.mode, provider: ctx.providerName, model, effort, instructionsVersion: CHAT_VERSION,
      worstCostUsd: worstCost, budgetUsd: settings.monthlyBudgetUsd, jobBudgetUsd: settings.jobBudgetUsd,
      perMinute: LIMITS.callsPerMinute, perDay: LIMITS.callsPerDay, callerPerDay: LIMITS.callsPerDay,
    })
    if (!reservation) {
      ctx.report('the budget could not be reserved, so nothing was sent')
      return fail('error', 'The AI budget could not be checked, so nothing was sent. Try again in a moment.')
    }
    if (reservation.kind === 'busy') {
      return fail('busy', `That is more than ${LIMITS.callsPerMinute} AI calls in a minute or ${LIMITS.callsPerDay} today. Wait a moment and try again.`)
    }
    row.id = reservation.id
    if (reservation.kind === 'budget') {
      row.outcome = 'budget'
      row.error = cutChars(reservationBudgetProblem(settings, job.title), RUN_ERROR_MAX)
      await finishCall(ctx.adminDb, row)
      return fail('budget', reservationBudgetProblem(settings, job.title))
    }

    // A new chat's row and its first message are written only now: a chat that was refused leaves nothing behind.
    if (pendingUser) {
      if (!conversation) {
        const problem = await createConversation(ctx.adminDb, {
          id: conversationId, user_id: ctx.userId, title: cutChars(text.replace(/\s+/g, ' '), 60), model, effort, thinking,
          tools_hash: hashes.tools, system_hash: hashes.system, tool_names: toolNames, mode: chatMode, owner_instructions: frozenInstructions,
        })
        if (problem) {
          row.outcome = 'error'; row.error = 'The chat could not be started.'
          await finishCall(ctx.adminDb, row)
          return fail('error', 'The chat could not be started. Try again in a moment.')
        }
        createdNow = true
        emit({ event: 'start', conversation_id: conversationId, is_new: true })
      } else emit({ event: 'start', conversation_id: conversationId, is_new: false })
      const wrote = await store('user', pendingUser.content, null, pendingUser.meta)
      pendingUser = null
      if (wrote !== 'ok') {
        row.outcome = 'error'; row.error = 'The message could not be stored.'
        await finishCall(ctx.adminDb, row)
        return fail(wrote === 'conflict' ? 'conflict' : 'error', wrote === 'conflict' ? 'Another message in this chat is still being answered. Wait for it, then try again.' : 'The message could not be saved, so nothing was sent. Try again in a moment.')
      }
    }

    const roundStarted = Date.now()
    const answer = await provider.chatRound(request, delta => {
      if (delta.kind === 'text') { streamed = true; emit({ event: 'text', t: delta.text }) }
      else if (delta.kind === 'tool') emit({ event: 'step', name: delta.name, label: STEP_LABELS[delta.name] ?? 'Working on it' })
    }).catch((): ModelFailure => ({ ok: false, kind: 'unknown', status: null, message: 'The AI call failed unexpectedly.', detail: '', requestId: null, sent: null }))
    row.duration_ms = Math.max(0, Date.now() - roundStarted)

    const usage: TokenUsage = answer.ok ? answer.usage : RUN_NO_TOKENS
    const price = costOf(usage, model, row.mode)
    row.input_tokens = usage.inputTokens
    row.cache_read_tokens = usage.cacheReadTokens
    row.cache_write_5m_tokens = usage.cacheWrite5mTokens
    row.cache_write_1h_tokens = usage.cacheWrite1hTokens
    row.output_tokens = usage.outputTokens
    row.thinking_tokens = usage.thinkingTokens
    row.long_prompt = price.longPrompt
    row.request_id = answer.requestId
    row.stop_reason = answer.ok ? answer.stopReason : null
    row.served_model = answer.ok ? answer.servedModel : null
    row.cost_usd = !answer.ok && RUN_MAY_BE_BILLED.includes(answer.kind) ? worstCost : price.costUsd
    costTotal += row.cost_usd

    // The ledger row of the round says how it ended; the text log (only while the owner keeps it on) says what was sent.
    const logRound = (): void => {
      row.tools = toolsRunThisRound
      if (!settings.logText) return
      row.request = trimForLog({
        conversation_id: conversationId, round, instructions_version: CHAT_VERSION, mode: chatMode, model, effort, thinking, tools: toolNames,
        ...(round === 1 ? { user_text: text, ...(newImages.length ? { photos: newImages.length } : {}) } : {}), ...(answer.sent ? { sent_to_provider: answer.sent } : {}),
      }, TEXT_LOG_MAX_BYTES)
      if (answer.ok) {
        row.response = trimForLog({ text: textOf(answer.content), ending: answer.ending, ...(answer.refusal ? { refusal: answer.refusal } : {}) }, TEXT_LOG_MAX_BYTES)
        row.thinking = answer.thinking ? trimText(answer.thinking, TEXT_LOG_MAX_BYTES) : null
      }
    }
    const toolsRunThisRound: ToolShape[] = []

    if (!answer.ok) {
      row.outcome = 'error'
      row.error = cutChars(hideSecrets(settings.logText ? `${answer.message}${answer.detail ? ` — ${answer.detail}` : ''}` : answer.message, ctx.secrets), RUN_ERROR_MAX)
      logRound()
      await finishCall(ctx.adminDb, row)
      // A round that was cut for taking too long: stopped, its row finished as an error (the worst case stays held, the
      // bill is unknown), nothing of it stored, and the person told plainly.
      return fail(answer.kind === 'timeout' ? 'timeout' : 'error', answer.message)
    }
    if (answer.ending === 'refused') {
      row.outcome = 'refused'
      row.error = cutChars(hideSecrets(settings.logText ? `The model declined to answer this one. — ${answer.refusal}` : 'The model declined to answer this one.', ctx.secrets), RUN_ERROR_MAX)
      logRound()
      await finishCall(ctx.adminDb, row)
      // A refusal can arrive after some text has streamed: that text is taken back, and nothing of the round is stored.
      return fail('declined', 'The model declined to answer this one. Try asking it in other words.')
    }
    const toolCalls = answer.content.filter(b => b.type === 'tool_use')
    const unusable = answer.ending === 'unexpected' || (answer.ending === 'cut_off' && toolCalls.length > 0) || (answer.ending === 'tool_calls' && toolCalls.length === 0) || holdsNul(answer.content)
    if (unusable) {
      row.outcome = answer.ending === 'cut_off' ? 'cut_off' : 'error'
      row.error = answer.ending === 'cut_off' ? `The answer was cut off at its limit of ${maxOutputTokens} tokens.` : `The model stopped in a way this app does not handle yet (${answer.stopReason}).`
      logRound()
      await finishCall(ctx.adminDb, row)
      return fail(answer.ending === 'cut_off' ? 'error' : 'error', answer.ending === 'cut_off' ? 'The answer was cut off before it finished. Ask a narrower question.' : 'The model stopped in a way this app does not handle yet.')
    }

    // The answer is stored exactly as it came (thinking blocks with their signatures included) and sent back unchanged.
    row.outcome = answer.ending === 'cut_off' ? 'cut_off' : 'ok'
    if (answer.ending === 'cut_off') row.error = `The answer was cut off at its limit of ${maxOutputTokens} tokens.`
    lastPrompt = usage.inputTokens + usage.cacheReadTokens + usage.cacheWrite5mTokens + usage.cacheWrite1hTokens
    const assistantMeta: Record<string, unknown> = {
      ...(answer.messageId ? { message_id: answer.messageId } : {}), round, ending: answer.ending, prompt_tokens: lastPrompt,
      ...(answer.cacheMiss ? { cache_miss: answer.cacheMiss } : {}), ...(answer.cleared ? { cleared: answer.cleared } : {}),
      cost_usd: row.cost_usd, run_id: runId,
    }
    if (answer.thinking) thinkingSummary = trimText(`${thinkingSummary}${thinkingSummary ? '\n\n' : ''}${answer.thinking}`, 8000)
    messages.push({ role: 'assistant', content: answer.content })
    answerMessages.push({ content: answer.content })
    if (answer.messageId) previousMessageId = answer.messageId

    if (answer.ending !== 'tool_calls') {
      logRound()
      await finishCall(ctx.adminDb, row)
      // The citations are checked BEFORE the answer is stored and kept with it, so a chat opened later shows the same links.
      finalCitations = await checkedCitations(ctx, answerMessages.flatMap(m => m.content), known)
      if (finalCitations.length) assistantMeta.citations = finalCitations
      // The kind of suggestion this answer noted stays with the answer, so a chat opened later shows the same line.
      const noted = suggestion as ChatSuggestionNote | null // set inside the tool step's closure: TypeScript cannot see it
      if (noted) assistantMeta.suggestion = { kind: noted.kind }
      const wrote = await store('assistant', answer.content, row.id, assistantMeta)
      if (wrote !== 'ok') return fail('error', 'The answer could not be saved. Try again in a moment.')
      await updateConversation(ctx.adminDb, ctx.userId, conversationId, { message_count: seq, last_prompt_tokens: lastPrompt, cost_usd: (conversation?.cost_usd ?? 0) + costTotal })
      endedWith = { text: textOf(answer.content) || NO_ANSWER, ending: answer.ending === 'cut_off' ? 'cut_off' : 'complete' }
      break
    }

    // 4 · The tools: side by side, as the owner, each with a time limit; every call gets a result, in the order asked.
    const wroteCall = await store('assistant', answer.content, row.id, assistantMeta)
    if (wroteCall !== 'ok') {
      logRound()
      await finishCall(ctx.adminDb, row)
      return fail('error', 'The answer could not be saved. Try again in a moment.')
    }
    // The caps: more than 8 calls in a round, or more than 3 proposals in an answer, are not run: each gets an error result.
    let writesLeft = CHAT_LIMITS.maxProposalsPerAnswer - proposals.length
    const verdicts = toolCalls.map((call, i): string | null => {
      if (i >= CHAT_LIMITS.maxToolCallsPerRound) return `Too many tool calls in one round (the most is ${CHAT_LIMITS.maxToolCallsPerRound}): this call did not run. Ask for fewer things at once.`
      if (chatToolKind(typeof call.name === 'string' ? call.name : '') === 'write') {
        if (writesLeft <= 0) return `At most ${CHAT_LIMITS.maxProposalsPerAnswer} proposals in one answer: this one did not run. Tell the person what is left to propose and let them ask again.`
        writesLeft -= 1
      }
      // One idea in an answer: a second note_shortcut gets an error result and never runs (the database caps them too).
      if (call.name === 'note_shortcut') {
        if (notesTried >= SUGGEST_LIMITS.perAnswer) return `At most ${SUGGEST_LIMITS.perAnswer} idea can be noted in one answer: this one did not run. Carry on with your answer.`
        notesTried += 1
      }
      return null
    })
    const results = await Promise.all(toolCalls.map(async (call, index): Promise<{ block: Block; shape: ToolShape; proposal: ProposalCard | null }> => {
      const toolStarted = Date.now()
      const name = typeof call.name === 'string' ? call.name : ''
      const id = typeof call.id === 'string' && TOOL_USE_ID.test(call.id) ? call.id : ''
      const timedOut: ToolOutput = { ok: false, message: 'That tool took too long. Try again with a narrower question, or answer without it.' }
      const blocked = verdicts[index]
      const output: ToolOutput = blocked
        ? { ok: false, message: blocked }
        : await withTimeout(
          runChatTool(name, call.input, toolNames, modes, {
            db: ctx.userDb, userId: ctx.userId, now, readAs: ctx.readAs,
            // The suggestions list is written by the service role, with the verified user id and a key made from the idea itself (the model never supplies one); the ledger row of this round is where it was first seen.
            noteIdea: async idea => addSuggestion(ctx.adminDb, ctx.userId, idea, await ideaKey(idea), 'answer', { times: 1, tokens: 0, cost: Math.round(costTotal * 1_000_000) / 1_000_000 }, row.id),
          }),
          CHAT_LIMITS.toolTimeoutMs, timedOut,
        )
      let finalOutput = output
      let card: ProposalCard | null = null
      // Only a write tool can make a proposal.
      if (output.ok && output.proposal && chatToolKind(name) === 'write') {
        const made = await makeProposal(ctx, conversationId, id, output.proposal, now)
        if (made) card = made
        else finalOutput = { ok: false, message: 'The proposal could not be saved. Try again.' }
      }
      if (output.ok && output.noted && !suggestion) suggestion = { kind: output.noted.kind }
      if (output.inputs) emit({ event: 'detail', name, input: output.inputs, ok: finalOutput.ok })
      const block = resultBlock(id, finalOutput)
      const bytes = JSON.stringify(block).length
      const fields = call.input !== null && typeof call.input === 'object' ? Object.entries(call.input as Record<string, unknown>).filter(([, v]) => v !== '' && v !== 'any' && v !== null && v !== undefined).map(([k]) => k) : []
      return {
        block,
        proposal: card,
        shape: { name, fields, ok: finalOutput.ok, rows: output.ok ? output.rows ?? null : null, bytes, ms: Date.now() - toolStarted, ...(output.ok && output.fingerprint ? { fingerprint: output.fingerprint } : {}) },
      }
    }))
    const resultBlocks = results.map(r => r.block)
    for (const r of results) {
      toolsRunThisRound.push(r.shape)
      toolsRun.push(r.shape)
      if (r.proposal) { proposals.push(r.proposal); emit({ event: 'proposal', ...r.proposal }) }
      for (const inner of Array.isArray(r.block.content) ? r.block.content as Block[] : []) if (inner.type === 'search_result' && typeof inner.source === 'string') known.add(inner.source)
    }
    logRound()
    await finishCall(ctx.adminDb, row)
    const wroteResults = await store('user', resultBlocks, null, {})
    if (wroteResults !== 'ok') return fail('error', 'The tool results could not be saved. Try again in a moment.')
    messages.push({ role: 'user', content: resultBlocks })
    // The wall inside an answer: this round's prompt + what it wrote + the new results is what the next request would carry.
    const nextPrompt = lastPrompt + usage.outputTokens + Math.ceil(JSON.stringify(resultBlocks).length / 3)
    if (nextPrompt >= CHAT_LIMITS.stopFromTokens) {
      await updateConversation(ctx.adminDb, ctx.userId, conversationId, { message_count: seq, last_prompt_tokens: lastPrompt, cost_usd: (conversation?.cost_usd ?? 0) + costTotal, status: 'full' })
      return fail('wall', 'This chat grew too long while looking things up. Start a new chat and ask again.')
    }
    if (nextPrompt >= CHAT_LIMITS.forceAnswerFromTokens) forceNoTools = true
    await updateConversation(ctx.adminDb, ctx.userId, conversationId, { message_count: seq, last_prompt_tokens: lastPrompt, cost_usd: (conversation?.cost_usd ?? 0) + costTotal })
  }

  if (!endedWith) return fail('error', 'The answer did not finish. Try again.')
  const citations = finalCitations
  // The wall after this answer: a prompt near the line means the next message would not fit.
  const wall = lastPrompt >= CHAT_LIMITS.wallTokens
  if (wall) await updateConversation(ctx.adminDb, ctx.userId, conversationId, { status: 'full' })
  return {
    event: 'done', conversation_id: conversationId, text: endedWith.text, citations, proposals, rounds: answerMessages.length,
    cost_usd: Math.round(costTotal * 1_000_000) / 1_000_000, wall, run_id: runId, ending: endedWith.ending,
    prompt_tokens: lastPrompt, thinking: thinkingSummary, suggestion,
  }
}

type ProposalCard = ChatProposalCard

/** Writes a proposal row for one tool call and returns the card; null when it could not be saved. One tool call makes one proposal. */
async function makeProposal(ctx: RunContext, conversationId: string, toolUseId: string, draft: ProposalDraft, now: Date): Promise<ProposalCard | null> {
  if (!TOOL_USE_ID.test(toolUseId)) return null
  const id = ctx.newId()
  const expiresAt = new Date(now.getTime() + CHAT_LIMITS.proposalHours * 3_600_000).toISOString()
  const saved = await insertProposal(ctx.adminDb, { id, user_id: ctx.userId, conversation_id: conversationId, tool_use_id: toolUseId, tool: draft.tool, args: draft.args, summary: draft.summary, expires_at: expiresAt })
  return saved ? { id, tool: draft.tool, summary: draft.summary, expires_at: expiresAt } : null
}

// ── The owner's tap ─────────────────────────────────────────────────────────

type ProposalDecision =
  | { ok: true; status: 'confirmed' | 'cancelled'; summary: string; result_id: string | null; tool: string; date?: string | null }
  | { ok: false; reason: 'bad_input' | 'not_found' | 'already_decided' | 'expired' | 'failed' | 'off' | 'error'; message: string }

/**
 * Confirm or Cancel of a proposal. The proposal is read BY ID AND VERIFIED USER (a forged or another account's id finds
 * nothing), decided at most once (the update only matches a row that is still pending), checked again with the same code
 * that made it, and written with the owner's own rights. A proposal that is expired or already decided writes nothing.
 */
async function decideChatProposal(ctx: RunContext, input: unknown): Promise<ProposalDecision> {
  if (ctx.caller !== 'app' || ctx.readAs !== 'owner') return { ok: false, reason: 'bad_input', message: 'A proposal can only be decided in the app.' }
  const id = ownValue(input, 'proposal_id')
  const decision = ownValue(input, 'decision')
  if (!isUuid(id) || (decision !== 'confirm' && decision !== 'cancel')) return { ok: false, reason: 'bad_input', message: 'That is not a proposal this app knows.' }
  const found = await readProposal(ctx.adminDb, ctx.userId, id)
  if (found.error) return { ok: false, reason: 'error', message: 'The proposal could not be read. Try again in a moment.' }
  const proposal = found.proposal
  if (!proposal) return { ok: false, reason: 'not_found', message: 'That proposal was not found.' }
  if (proposal.status !== 'pending') return { ok: false, reason: 'already_decided', message: `That proposal was already ${proposal.status === 'confirmed' ? 'confirmed' : proposal.status === 'cancelled' ? 'cancelled' : 'decided (saving it failed)'}.` }
  const now = ctx.now()
  // Fail closed: a date that cannot be read counts as expired.
  if (!(Date.parse(proposal.expires_at) > now.getTime())) {
    await decideProposal(ctx.adminDb, ctx.userId, id, 'cancelled', now.toISOString())
    return { ok: false, reason: 'expired', message: 'That proposal expired. Ask again.' }
  }
  if (decision === 'cancel') {
    const won = await decideProposal(ctx.adminDb, ctx.userId, id, 'cancelled', now.toISOString())
    return won ? { ok: true, status: 'cancelled', summary: proposal.summary, result_id: null, tool: proposal.tool } : { ok: false, reason: 'already_decided', message: 'That proposal was already decided.' }
  }
  // The owner may edit the title and the date on the card; the edited values go through the same check as the proposal did.
  const today = osloDay(now)
  const editedTitle = ownValue(input, 'title')
  const editedDate = ownValue(input, 'date')
  if ((editedTitle !== undefined && typeof editedTitle !== 'string') || (editedDate !== undefined && typeof editedDate !== 'string')) {
    return { ok: false, reason: 'bad_input', message: 'The title and the date must be text.' }
  }
  const stored = proposal.args !== null && typeof proposal.args === 'object' && !Array.isArray(proposal.args) ? proposal.args as Record<string, unknown> : {}
  const merged: Record<string, unknown> = {
    ...stored,
    ...(editedTitle !== undefined ? { title: editedTitle } : {}),
    ...(editedDate !== undefined ? (proposal.tool === 'add_task' ? { due_date: editedDate === '' ? null : editedDate } : { date: editedDate }) : {}),
  }
  // The tool must still be "ask first": a tool the owner has since switched off writes nothing (the setting is read now, not when the chat began).
  const controls = await readChatControls(ctx.userDb, ctx.userId)
  if (!controls) return { ok: false, reason: 'error', message: 'Your Ask AI settings could not be read, so nothing was saved. Try again in a moment.' }
  if (controls.modes[proposal.tool === 'add_task' ? 'propose_add_task' : 'propose_log_food'] !== 'ask') {
    await decideProposal(ctx.adminDb, ctx.userId, id, 'cancelled', now.toISOString())
    return { ok: false, reason: 'off', message: 'That kind of change is switched off for Ask AI, so nothing was saved.' }
  }
  // Check before claiming, so a stored or edited value that does not pass never uses up the one decision as a success.
  const rechecked = checkedProposal(proposal.tool, merged, today)
  if (!rechecked.ok) {
    if (editedTitle !== undefined || editedDate !== undefined) return { ok: false, reason: 'bad_input', message: rechecked.message }
    await decideProposal(ctx.adminDb, ctx.userId, id, 'failed', now.toISOString())
    return { ok: false, reason: 'failed', message: 'That proposal is not valid any more, so nothing was saved.' }
  }
  const won = await decideProposal(ctx.adminDb, ctx.userId, id, 'confirmed', now.toISOString(), rechecked.draft.args)
  if (!won) return { ok: false, reason: 'already_decided', message: 'That proposal was already decided.' }
  const written = await applyProposal(ctx.userDb, ctx.userId, proposal.tool, rechecked.draft.args, today)
  if (!written.ok) {
    await markProposalFailed(ctx.adminDb, ctx.userId, id)
    return { ok: false, reason: 'failed', message: written.message }
  }
  await setProposalResult(ctx.adminDb, ctx.userId, id, written.id)
  return { ok: true, status: 'confirmed', summary: rechecked.draft.summary, result_id: written.id, tool: proposal.tool, date: proposal.tool === 'log_food' ? String(rechecked.draft.args.date) : null }
}

/** Deletes a chat softly (the Undo window; ai_chats_purge removes it for good later) or brings it back. */
async function setChatDeleted(ctx: RunContext, input: unknown, deleted: boolean): Promise<{ ok: true; id: string; title: string } | { ok: false; reason: 'bad_input' | 'not_found' | 'error'; message: string }> {
  if (ctx.caller !== 'app' || ctx.readAs !== 'owner') return { ok: false, reason: 'bad_input', message: 'A chat can only be deleted in the app.' }
  const id = ownValue(input, 'conversation_id')
  if (!isUuid(id)) return { ok: false, reason: 'bad_input', message: 'That is not a chat this app knows.' }
  const found = await readConversation(ctx.adminDb, ctx.userId, id)
  if (found.error) return { ok: false, reason: 'error', message: 'The chat could not be read. Try again in a moment.' }
  const c = found.conversation
  // Deleting needs a chat that is there; restoring needs one that is deleted (and not yet purged).
  if (!c || (deleted ? c.deleted_at !== null : c.deleted_at === null)) return { ok: false, reason: 'not_found', message: deleted ? 'That chat was already deleted.' : 'That chat is not there to restore.' }
  const changed = await setConversationDeleted(ctx.adminDb, ctx.userId, id, deleted ? ctx.now().toISOString() : null)
  return changed ? { ok: true, id, title: c.title ?? 'Chat' } : { ok: false, reason: 'error', message: 'The chat could not be changed. Try again in a moment.' }
}

// ═══ supabase/claude-src/phone-ask.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · the phone's question with tools (phase 4b)
//
//  `phone_ask` used to be one model call with no tools: the gateway looked a small context up by code and handed it
//  over. Now the model may also read, through tools of its own (the day's plan, a week's figures, a day's food, a
//  words search), when the context does not already answer. The limits that keep it a phone answer:
//
//    · a small read-only set (`phoneChatTools`: day plan, week figures, food day, find text, About me; no proposals, no
//      database tool, nothing that writes) that FOLLOWS THE OWNER'S CONTROLS like the chat does: a tool switched off in
//      Settings is not offered, and the owner's own instructions go in as the same second system block. The code decides
//      which tools exist at all; the settings can only take some away. The device path may not name another tool;
//    · at most two requests: the first may call tools, the second may not (an answer always ends in words), and at most
//      four tool calls run, side by side, each with a short time limit;
//    · low effort, thinking off, not streamed to the phone, and under 19 seconds in all (the gateway gives up at 22);
//    · every round is reserved against the budget and ledgered under the same run_id, the device's 100 calls a day and
//      the master switch and the job's switch apply like any call. Nothing is stored (no conversation).
//
//  The tools run with the service client, so EVERY query names the verified user id (`HEVY_USER_ID` from this
//  function's own environment, set by main.ts for a device caller): a device never names an account, a table or a query.
//  What a tool returns is data in a `tool_result` block, never an instruction (said in the instructions).
// ─────────────────────────────────────────────────────────────────────────────

/** The whole question, tools included, is over after this long: the gateway gives up at 22 s. */
const PHONE_DEADLINE_MS = 19_000
/** One tool may take this long: a slower one is an error result, not a hung answer. */
const PHONE_TOOL_MS = 5_000

const phoneTextOf = (content: readonly Block[]): string => content.filter(b => b.type === 'text' && typeof b.text === 'string').map(b => b.text as string).join('')

async function phoneWithTimeout<T>(run: Promise<T>, ms: number, onTimeout: T): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const late = new Promise<T>(resolve => { timer = setTimeout(() => resolve(onTimeout), ms) })
  try { return await Promise.race([run, late]) } finally { if (timer) clearTimeout(timer) }
}

async function runPhoneAsk(ctx: RunContext, input: unknown): Promise<RunReply> {
  const job = PHONE_ASK_JOB
  const started = Date.now()
  const runId = ctx.newId()
  const base = newRow(ctx, job)
  base.run_id = runId
  /** Ends the run before any model call: a ledger row with no tokens and the reason. */
  const stop = async (reason: 'bad_input' | 'off' | 'not_configured' | 'error', message: string): Promise<RunReply> => {
    base.outcome = reason
    base.error = cutChars(message, RUN_ERROR_MAX)
    const problem = await writeCall(ctx.adminDb, base)
    if (problem) ctx.report(`a call was not written to the ledger: ${problem}`)
    return { ok: false, reason, message, call: summaryOf(base) }
  }

  // 1 · The walls, in the order of runJob: the device's caller, the rate caps, the input, the settings, the switches, the key.
  if (ctx.caller !== 'phone') return { ok: false, reason: 'bad_input', message: `"${job.title}" can't be started from here.` }
  const gate = await readGate(ctx.userDb, job.name, gateScopeOf(ctx))
  if (!gate) {
    ctx.report('the usage could not be read, so nothing was sent')
    return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was sent. Try again in a moment.' }
  }
  const tooMany = rateCapProblem(gate, ctx.caller)
  if (tooMany) return { ok: false, reason: 'busy', message: tooMany }
  const prepared = job.prepare(input, ctx.now())
  if ('problem' in prepared) return stop('bad_input', prepared.problem)
  const stored = await readSettingRows(ctx.userDb, ctx.userId, job.name)
  if (!stored) return stop('error', 'Your AI settings could not be read, so nothing was sent. Try again in a moment.')
  const settings = settingsFor(job, stored.account, stored.job)
  if (!settings.aiEnabled) return stop('off', 'All AI is switched off in Developer → AI → Settings.')
  if (!settings.enabled) return stop('off', `"${job.title}" is switched off in Developer → AI → Settings.`)
  const provider = ctx.provider
  if (!provider) return stop('not_configured', 'AI is not set up yet: the server has no API key for it.')

  // 1b · The owner's controls, read as input (any failure reading the tool rows: nothing is sent): the tools that are on, and their words.
  const controls = await readChatControls(ctx.userDb, ctx.userId)
  if (!controls) return stop('error', 'Your Ask AI settings could not be read, so nothing was sent. Try again in a moment.')
  const toolNames = phoneToolNames(controls.modes)
  const ownerInstructions = ownerInstructionsBlock(controls.instructions)

  // 2 · The rounds: the first may call a tool, the second may not.
  const tools = phoneChatTools(toolNames)
  const messages: ChatMessage[] = [{ role: 'user', content: [{ type: 'text', text: prepared.userText }] }]
  let lastRow: CallRow = base
  for (let round = 1; round <= CHAT_LIMITS.phoneRounds; round++) {
    const remaining = PHONE_DEADLINE_MS - (Date.now() - started)
    if (remaining < 3000) return { ok: false, reason: 'error', message: 'That took too long for the phone. Try again in a moment.', call: summaryOf(lastRow) }
    const noTools = round === CHAT_LIMITS.phoneRounds || tools.length === 0
    const request: ChatRequest = {
      model: settings.model, maxOutputTokens: settings.maxOutputTokens, effort: settings.effort, thinking: 'off',
      system: job.instructions, ownerInstructions, tools, noTools, messages, previousMessageId: null,
      contextEditing: { ...CHAT_LIMITS.contextEditing }, timeoutMs: remaining,
      firstEventTimeoutMs: Math.min(CHAT_LIMITS.firstEventMs, remaining), idleTimeoutMs: Math.min(CHAT_LIMITS.idleMs, remaining),
    }
    const row: CallRow = newRow(ctx, job)
    row.run_id = runId
    row.step = round
    row.model = settings.model
    row.effort = settings.effort
    lastRow = row
    const worstCost = worstCostOf(settings.model, job.instructions.length + ownerInstructions.length + JSON.stringify(tools).length + JSON.stringify(messages).length, settings.maxOutputTokens)
    const reservation = await reserveCall(ctx.adminDb, {
      userId: ctx.userId, job: job.name, caller: ctx.caller, mode: row.mode, provider: ctx.providerName, model: settings.model, effort: settings.effort,
      instructionsVersion: job.version, worstCostUsd: worstCost, budgetUsd: settings.monthlyBudgetUsd, jobBudgetUsd: settings.jobBudgetUsd,
      perMinute: LIMITS.callsPerMinute, perDay: LIMITS.callsPerDay, callerPerDay: callerDailyCap(ctx.caller),
    })
    if (!reservation) {
      ctx.report('the budget could not be reserved, so nothing was sent')
      return { ok: false, reason: 'error', message: 'The AI budget could not be checked, so nothing was sent. Try again in a moment.' }
    }
    if (reservation.kind === 'busy') {
      return { ok: false, reason: 'busy', message: `That is more than ${LIMITS.callsPerMinute} AI calls in a minute, ${LIMITS.callsPerDay} today, or ${callerDailyCap(ctx.caller)} in 24 hours from this device. Wait a moment and try again.` }
    }
    row.id = reservation.id
    if (reservation.kind === 'budget') {
      row.outcome = 'budget'
      row.error = cutChars(reservationBudgetProblem(settings, job.title), RUN_ERROR_MAX)
      await finishCall(ctx.adminDb, row)
      return { ok: false, reason: 'budget', message: reservationBudgetProblem(settings, job.title), call: summaryOf(row) }
    }

    const roundStarted = Date.now()
    const answer = await provider.chatRound(request, () => {}).catch((): ModelFailure => ({ ok: false, kind: 'unknown', status: null, message: 'The AI call failed unexpectedly.', detail: '', requestId: null, sent: null }))
    row.duration_ms = Math.max(0, Date.now() - roundStarted)
    const usage: TokenUsage = answer.ok ? answer.usage : RUN_NO_TOKENS
    const price = costOf(usage, settings.model, row.mode)
    row.input_tokens = usage.inputTokens
    row.cache_read_tokens = usage.cacheReadTokens
    row.cache_write_5m_tokens = usage.cacheWrite5mTokens
    row.cache_write_1h_tokens = usage.cacheWrite1hTokens
    row.output_tokens = usage.outputTokens
    row.thinking_tokens = usage.thinkingTokens
    row.long_prompt = price.longPrompt
    row.request_id = answer.requestId
    row.stop_reason = answer.ok ? answer.stopReason : null
    row.served_model = answer.ok ? answer.servedModel : null
    row.cost_usd = !answer.ok && RUN_MAY_BE_BILLED.includes(answer.kind) ? worstCost : price.costUsd
    const logRound = (toolShapes: { name: string; ok: boolean; ms: number }[]): void => {
      row.tools = toolShapes
      if (!settings.logText) return
      row.request = trimForLog({ instructions_version: job.version, round, model: settings.model, tools: tools.map(t => t.name), ...(round === 1 ? { user_text: prepared.userText } : {}), ...(answer.ok && answer.sent ? { sent_to_provider: answer.sent } : {}) }, TEXT_LOG_MAX_BYTES)
      if (answer.ok) row.response = trimForLog({ text: phoneTextOf(answer.content), ending: answer.ending }, TEXT_LOG_MAX_BYTES)
    }
    const fail = async (outcome: 'error' | 'refused' | 'cut_off', message: string, logLine: string): Promise<RunReply> => {
      row.outcome = outcome
      row.error = cutChars(hideSecrets(settings.logText ? logLine : message, ctx.secrets), RUN_ERROR_MAX)
      logRound([])
      await finishCall(ctx.adminDb, row)
      return { ok: false, reason: outcome, message: hideSecrets(message, ctx.secrets), call: summaryOf(row) }
    }
    if (!answer.ok) return fail('error', answer.message, answer.detail ? `${answer.message} — ${answer.detail}` : answer.message)
    if (answer.ending === 'refused') return fail('refused', 'The model declined to answer this one.', `The model declined to answer this one. — ${answer.refusal}`)
    if (answer.ending === 'cut_off') return fail('cut_off', `The answer was cut off at its limit of ${settings.maxOutputTokens} tokens. Raise the longest answer for this job in Developer → AI → Settings.`, 'cut off')

    const calls = answer.content.filter(b => b.type === 'tool_use')
    if (answer.ending === 'tool_calls') {
      // The last round may not call a tool; a model that did anyway has no answer, which is a failure, never a loop.
      if (noTools || !calls.length) return fail('error', 'The model stopped in a way this app does not handle yet.', `unexpected tool call (${answer.stopReason})`)
      messages.push({ role: 'assistant', content: answer.content })
      const shapes: { name: string; ok: boolean; ms: number }[] = []
      const results = await Promise.all(calls.map(async (call, index): Promise<Block> => {
        const at = Date.now()
        const id = typeof call.id === 'string' && /^[A-Za-z0-9_-]{1,100}$/.test(call.id) ? call.id : ''
        const name = typeof call.name === 'string' ? call.name : ''
        const output: ToolOutput = index >= CHAT_LIMITS.phoneToolCalls
          ? { ok: false, message: `Too many tool calls (the most is ${CHAT_LIMITS.phoneToolCalls}): this one did not run. Answer with what you have.` }
          : await phoneWithTimeout(runPhoneTool(name, call.input, toolNames, { db: ctx.userDb, userId: ctx.userId, now: ctx.now(), readAs: ctx.readAs }),
            Math.min(PHONE_TOOL_MS, Math.max(1000, PHONE_DEADLINE_MS - (Date.now() - started) - 3000)), { ok: false, message: 'That tool took too long. Answer without it.' } as ToolOutput)
        shapes.push({ name, ok: output.ok, ms: Date.now() - at })
        return output.ok
          ? { type: 'tool_result', tool_use_id: id, content: output.blocks && output.blocks.length ? output.blocks : output.text }
          : { type: 'tool_result', tool_use_id: id, content: output.message, is_error: true }
      }))
      row.outcome = 'ok'
      logRound(shapes)
      await finishCall(ctx.adminDb, row)
      messages.push({ role: 'user', content: results })
      continue
    }

    // The answer: the job's own check (length, plain text), never repaired.
    let check
    try { check = prepared.read(phoneTextOf(answer.content), { thinking: answer.thinking, servedModel: answer.servedModel, webSearches: 0 }) } catch { check = { ok: false as const, problem: 'its check failed' } }
    if (!check.ok) {
      row.outcome = 'invalid'
      row.error = cutChars(`The model's answer could not be used: ${check.problem}.`, RUN_ERROR_MAX)
      logRound([])
      await finishCall(ctx.adminDb, row)
      return { ok: false, reason: 'invalid', message: `The model's answer could not be used: ${check.problem}.`, call: summaryOf(row) }
    }
    row.outcome = 'ok'
    logRound([])
    await finishCall(ctx.adminDb, row)
    return { ok: true, job: job.name, result: check.result, call: summaryOf(row) }
  }
  return { ok: false, reason: 'error', message: 'The answer did not finish. Try again.', call: summaryOf(lastRow) }
}

// ═══ supabase/claude-src/diagnose.ts ═══
// ─────────────────────────────────────────────────────────────────────────────
//  The `claude` function · Diagnose
//
//  `{ action: 'diagnose' }`, behind the Diagnose button on Developer → AI → How
//  it works. When ✨ is slow or times out, this answers the one question that
//  matters: does the request not reach Anthropic at all, or does Anthropic get
//  it and take long? Four checks, in order, each timed:
//    1 · Network and key   list the models (free)
//    2 · Request shape     count the tokens of ✨'s real request (free): a 400 here would say the answer shape is refused
//    3 · Tiny answer       the job `diagnose` ("Reply with the word OK.") through the normal run path
//    4 · ✨'s real request  the job `item_fill` with a made-up sentence, through the normal run path, 90 s limit
//  Steps 3 and 4 are real calls: each is reserved against the budget and written to the ledger like any other.
//  Nothing in a request chooses anything here: the sentence, the models and the limits are fixed in this file.
//
//  The answer carries only our own sentences and numbers. A message goes out through hideSecrets, and no raw
//  provider object is ever put in one.
//
//  A fifth check, the chat's own real request, is asked for apart (`part: 'chat'`, `runDiagnoseChat` at the end): its
//  120 s limit and the four checks together would pass Supabase's 150 s.
// ─────────────────────────────────────────────────────────────────────────────

/** The made-up sentence every check uses: ✨'s own example. No personal data. */
const DIAGNOSE_SENTENCE = 'Dentist on Tuesday at 14:00 for an hour at Jernbanetorget, remind me a day before'

/** At most one Diagnose a minute for an account: the `diagnose` rows of the ledger are the count. */
const DIAGNOSE_PAUSE_MS = 60_000
/** Steps 1 to 3 wait at most this long each. */
const DIAGNOSE_SHORT_MS = 20_000
/** Step 4 waits this long: three times ✨'s own 30 s, so its true time shows. */
const DIAGNOSE_LONG_MS = 90_000
/** The whole action stays under Supabase's 150 s limit, with room to answer. */
const DIAGNOSE_TOTAL_MS = 140_000
// A step 4 with less time than this left would only time out: it is skipped and says so.
const DIAGNOSE_LONG_MIN_MS = 10_000
const DIAGNOSE_DETAIL_MAX = 400
// ✨'s default model: the list must hold it for ✨ to work with its default settings.
const FILL_MODEL = 'claude-haiku-5-5'

const diagnoseSecs = (ms: number) => (ms / 1000).toFixed(1)
const diagnoseUsd = (usd: number) => `$${usd.toFixed(5)}`
const diagnoseTokens = (n: number) => `${n} token${n === 1 ? '' : 's'}`

/** One plain sentence for a failed call: our own wording, the status and the provider's short explanation. */
function diagnoseFailure(what: string, failure: ModelFailure, ms: number): string {
  const status = failure.status === null ? '' : ` (HTTP ${failure.status})`
  const said = failure.detail ? ` Anthropic says: ${failure.detail}` : ''
  return `${what} failed after ${diagnoseSecs(ms)} s${status}: ${failure.message}${said}`
}

/** What a real call (steps 3 and 4) amounts to, as one sentence. */
function diagnoseRunSentence(what: string, reply: RunReply, ms: number): string {
  if (reply.ok) {
    const c = reply.call
    // Only a job with a step before the model can answer without a call; Diagnose runs none of those.
    if (!c) return `${what} came back in ${diagnoseSecs(ms)} s without asking the model.`
    const promptTokens = c.input_tokens + c.cache_read_tokens + c.cache_write_tokens
    return `${what} came back in ${diagnoseSecs(ms)} s: ${diagnoseTokens(promptTokens)} in, ${diagnoseTokens(c.output_tokens)} out (${c.thinking_tokens} of them thinking), cost ${diagnoseUsd(c.cost_usd)}.`
  }
  const c = reply.call
  const numbers = c && (c.input_tokens || c.output_tokens)
    ? ` It used ${diagnoseTokens(c.input_tokens + c.cache_read_tokens + c.cache_write_tokens)} in and ${diagnoseTokens(c.output_tokens)} out.`
    : ' It used 0 tokens.'
  return `${what} did not give a usable answer after ${diagnoseSecs(ms)} s (${reply.reason}): ${reply.message}${numbers}`
}

async function runDiagnose(ctx: RunContext): Promise<DiagnoseReply> {
  // One a minute: a Diagnose leaves a `diagnose` row in the ledger (step 3 reserves one even when the budget
  // refuses it), so the ledger itself is the clock. A read that fails answers "error": nothing runs unchecked.
  const since = new Date(ctx.now().getTime() - DIAGNOSE_PAUSE_MS).toISOString()
  const recent = await hasRecentCall(ctx.userDb, ctx.userId, 'diagnose', since)
  if (recent === null) return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was tried. Try again in a moment.' }
  if (recent) return { ok: false, reason: 'busy', message: 'Diagnose already ran in the last minute. Wait a moment and run it again.' }

  const started = Date.now()
  const steps: DiagnoseStep[] = []
  /** Runs one check, times it and records its sentence. A check that throws is a failed check, never a crash. */
  const check = async (name: DiagnoseStep['name'], title: string, body: () => Promise<{ ok: boolean; detail: string }>): Promise<void> => {
    const t0 = Date.now()
    let outcome: { ok: boolean; detail: string }
    try {
      outcome = await body()
    } catch (error) {
      ctx.report(`a diagnose step threw: ${errorPlace(error)}`)
      outcome = { ok: false, detail: 'This check failed in a way the function does not know.' }
    }
    steps.push({ name, title, ok: outcome.ok, ms: Math.max(0, Date.now() - t0), detail: cutChars(hideSecrets(outcome.detail, ctx.secrets), DIAGNOSE_DETAIL_MAX) })
  }
  const provider = ctx.provider

  // 1 · Network and key.
  let reached = false
  await check('network_key', 'Network and key', async () => {
    if (!provider) return { ok: false, detail: 'The server has no Anthropic key (ANTHROPIC_API_KEY is not set), so nothing was tried.' }
    const t0 = Date.now()
    const list = await provider.listModels(DIAGNOSE_SHORT_MS)
    const ms = Date.now() - t0
    if (!list.ok) return { ok: false, detail: diagnoseFailure('Listing the models', list, ms) }
    reached = true
    const has = list.modelIds.includes(FILL_MODEL)
    return {
      ok: has,
      detail: `Anthropic listed ${list.modelIds.length} model${list.modelIds.length === 1 ? '' : 's'} in ${diagnoseSecs(ms)} s, so the network and the key work; ${FILL_MODEL} ${has ? 'is' : 'is NOT'} in the list.`,
    }
  })
  // Without a connection nothing after it can tell us anything.
  if (!reached || !provider) return { ok: true, steps }

  // The request ✨ sends, built the way a run builds it (the owner's own settings for the job included).
  const fillJob = findJob('item_fill')
  const prepared = fillJob ? fillJob.prepare({ text: DIAGNOSE_SENTENCE }, ctx.now()) : { problem: 'the ✨ job is missing' }
  const stored = await readSettingRows(ctx.userDb, ctx.userId, 'item_fill')
  const settings = fillJob ? settingsFor(fillJob, stored?.account ?? null, stored?.job ?? null) : null

  // 2 · Request shape.
  await check('request_shape', 'Request shape', async () => {
    if (!fillJob || !settings || 'problem' in prepared) return { ok: false, detail: 'The ✨ request could not be built here.' }
    const request: ModelRequest = {
      model: settings.model, maxOutputTokens: settings.maxOutputTokens, effort: settings.effort, instructions: fillJob.instructions,
      userText: prepared.userText, answerSchema: fillJob.enforceAnswerSchema ? fillJob.answerSchema : null, thinking: settings.thinking, timeoutMs: DIAGNOSE_SHORT_MS,
    }
    const t0 = Date.now()
    const count = await provider.countTokens(request)
    const ms = Date.now() - t0
    if (count.ok) return { ok: true, detail: `Anthropic accepted ✨'s request and its answer shape and counted ${diagnoseTokens(count.inputTokens)} in ${diagnoseSecs(ms)} s.` }
    const refused = count.kind === 'refused_request' ? ' The request as built is refused, so the answer shape may be the problem.' : ''
    return { ok: false, detail: `${diagnoseFailure('Counting the tokens', count, ms)}${refused}` }
  })

  // 3 · A tiny answer, through the normal run path.
  await check('tiny_answer', 'Tiny answer', async () => {
    const t0 = Date.now()
    const reply = await runJob({ ...ctx, timeoutMs: DIAGNOSE_SHORT_MS }, 'diagnose', {})
    return { ok: reply.ok, detail: diagnoseRunSentence('A tiny answer', reply, Date.now() - t0) }
  })

  // 4 · ✨'s real request, with room: 90 s, or what is left of the whole action.
  const timeLeft = DIAGNOSE_TOTAL_MS - (Date.now() - started)
  const longLimit = Math.min(DIAGNOSE_LONG_MS, timeLeft)
  await check('fill_request', "✨'s real request", async () => {
    if (longLimit < DIAGNOSE_LONG_MIN_MS) {
      return { ok: false, detail: `Skipped: the earlier checks used ${diagnoseSecs(DIAGNOSE_TOTAL_MS - Math.max(timeLeft, 0))} s of the ${DIAGNOSE_TOTAL_MS / 1000} s this action has in all.` }
    }
    const t0 = Date.now()
    const reply = await runJob({ ...ctx, timeoutMs: longLimit }, 'item_fill', { text: DIAGNOSE_SENTENCE })
    return { ok: reply.ok, detail: diagnoseRunSentence("✨'s request", reply, Date.now() - t0) }
  })

  return { ok: true, steps }
}

// ── The chat's own request (a fifth check, asked for apart) ──────────────────

/** The question of the chat check: made up, about nothing personal. */
const DIAGNOSE_CHAT_QUESTION = 'What is on my plan today?'
/** The chat check waits this long for the whole round, the first event included. A call of its own: the four checks plus this would pass Supabase's 150 s. */
const DIAGNOSE_CHAT_MS = 120_000

/**
 * `{ action: 'diagnose', part: 'chat' }`: the chat's REAL first request (its real tools and instructions, the date line and
 * a fixed question) sent once with a 120 s limit, to see how long Anthropic takes to start answering and to finish. A tool
 * the model asks for is not run: asking for one is an answer. It is one real call, reserved against the budget and written to
 * the ledger as a round of the job `chat` (its request text says it is Diagnose).
 */
async function runDiagnoseChat(ctx: RunContext): Promise<DiagnoseReply> {
  // The same one-a-minute pause as Diagnose, kept by the ledger: its rows are the chat's step 1 with `diagnose` in the request.
  const since = new Date(ctx.now().getTime() - DIAGNOSE_PAUSE_MS).toISOString()
  const recent = await hasRecentChatDiagnose(ctx.userDb, ctx.userId, since)
  if (recent === null) return { ok: false, reason: 'error', message: 'The AI usage could not be read, so nothing was tried. Try again in a moment.' }
  if (recent) return { ok: false, reason: 'busy', message: 'The chat check already ran in the last minute. Wait a moment and run it again.' }
  const provider = ctx.provider
  const title = "The chat's real request"
  if (!provider) return { ok: true, steps: [{ name: 'chat_request', title, ok: false, ms: 0, detail: 'The server has no Anthropic key (ANTHROPIC_API_KEY is not set), so nothing was tried.' }] }
  const stored = await readSettingRows(ctx.userDb, ctx.userId, CHAT_JOB.name)
  if (!stored) return { ok: false, reason: 'error', message: 'The AI settings could not be read, so nothing was tried. Try again in a moment.' }
  const settings = settingsFor(CHAT_JOB, stored.account, stored.job)
  const tools = chatToolsNamed(toolsForNewChat(toolModes(null)))
  const now = ctx.now()
  const request: ChatRequest = {
    model: settings.model, maxOutputTokens: Math.max(CHAT_LIMITS.minOutputTokens, settings.maxOutputTokens), effort: settings.effort, thinking: settings.thinking,
    system: CHAT_SYSTEM, ownerInstructions: '', tools, noTools: false,
    messages: [{ role: 'user', content: [{ type: 'text', text: liveContextText(now) }, { type: 'text', text: DIAGNOSE_CHAT_QUESTION }] }],
    previousMessageId: null, contextEditing: { ...CHAT_LIMITS.contextEditing }, timeoutMs: DIAGNOSE_CHAT_MS,
  }
  const step = (ok: boolean, ms: number, detail: string): DiagnoseReply => ({
    ok: true, steps: [{ name: 'chat_request', title, ok, ms: Math.max(0, ms), detail: cutChars(hideSecrets(detail, ctx.secrets), DIAGNOSE_DETAIL_MAX) }],
  })

  const row = newRow(ctx, CHAT_JOB)
  row.model = settings.model
  row.effort = settings.effort
  row.instructions_version = CHAT_VERSION
  const worstCost = worstCostOf(settings.model, CHAT_SYSTEM.length + JSON.stringify(tools).length + 400, request.maxOutputTokens)
  const reservation = await reserveCall(ctx.adminDb, {
    userId: ctx.userId, job: CHAT_JOB.name, caller: ctx.caller, mode: row.mode, provider: ctx.providerName, model: settings.model, effort: settings.effort,
    instructionsVersion: CHAT_VERSION, worstCostUsd: worstCost, budgetUsd: settings.monthlyBudgetUsd, jobBudgetUsd: settings.jobBudgetUsd,
    perMinute: LIMITS.callsPerMinute, perDay: LIMITS.callsPerDay, callerPerDay: LIMITS.callsPerDay,
  })
  if (!reservation) return { ok: false, reason: 'error', message: 'The AI budget could not be checked, so nothing was tried. Try again in a moment.' }
  if (reservation.kind === 'busy') return { ok: false, reason: 'busy', message: `That is more than ${LIMITS.callsPerMinute} AI calls in a minute or ${LIMITS.callsPerDay} today. Wait a moment and run it again.` }
  row.id = reservation.id
  if (reservation.kind === 'budget') {
    row.outcome = 'budget'
    row.error = cutChars(reservationBudgetProblem(settings, CHAT_JOB.title), RUN_ERROR_MAX)
    await finishCall(ctx.adminDb, row)
    return step(false, 0, reservationBudgetProblem(settings, CHAT_JOB.title))
  }

  const t0 = Date.now()
  let firstAt: number | null = null
  const answer = await provider.chatRound(request, delta => { if (delta.kind === 'started' && firstAt === null) firstAt = Date.now() - t0 })
    .catch((): ModelFailure => ({ ok: false, kind: 'unknown', status: null, message: 'The AI call failed unexpectedly.', detail: '', requestId: null, sent: null }))
  const ms = Date.now() - t0
  row.duration_ms = ms
  const usage = answer.ok ? answer.usage : RUN_NO_TOKENS
  const price = costOf(usage, settings.model, row.mode)
  row.input_tokens = usage.inputTokens
  row.cache_read_tokens = usage.cacheReadTokens
  row.cache_write_5m_tokens = usage.cacheWrite5mTokens
  row.cache_write_1h_tokens = usage.cacheWrite1hTokens
  row.output_tokens = usage.outputTokens
  row.thinking_tokens = usage.thinkingTokens
  row.long_prompt = price.longPrompt
  row.request_id = answer.requestId
  row.stop_reason = answer.ok ? answer.stopReason : null
  row.served_model = answer.ok ? answer.servedModel : null
  row.cost_usd = !answer.ok && RUN_MAY_BE_BILLED.includes(answer.kind) ? worstCost : price.costUsd
  row.request = trimForLog({ diagnose: true, question: DIAGNOSE_CHAT_QUESTION, tools: tools.map(t => t.name) }, TEXT_LOG_MAX_BYTES)
  const first = firstAt === null ? 'no event came' : `the first event came after ${diagnoseSecs(firstAt)} s`
  if (!answer.ok) {
    row.outcome = 'error'
    row.error = cutChars(hideSecrets(answer.message, ctx.secrets), RUN_ERROR_MAX)
    await finishCall(ctx.adminDb, row)
    return step(false, ms, `The chat's request failed after ${diagnoseSecs(ms)} s (${first}): ${answer.message}${answer.detail ? ` Anthropic says: ${answer.detail}` : ''}`)
  }
  row.outcome = answer.ending === 'refused' ? 'refused' : 'ok'
  await finishCall(ctx.adminDb, row)
  const asked = answer.content.filter(b => b.type === 'tool_use').map(b => (typeof b.name === 'string' ? b.name : '?')).slice(0, 4)
  const ended = answer.ending === 'tool_calls' ? `the model asked for ${asked.join(', ') || 'a tool'} (not run here)` : answer.ending === 'refused' ? 'the model declined' : 'the model answered in words'
  const promptTokens = usage.inputTokens + usage.cacheReadTokens + usage.cacheWrite5mTokens + usage.cacheWrite1hTokens
  return step(true, ms, `The chat's request came back: ${first}, finished after ${diagnoseSecs(ms)} s; ${ended}; ${diagnoseTokens(promptTokens)} in, ${diagnoseTokens(usage.outputTokens)} out, cost ${diagnoseUsd(price.costUsd)}.`)
}

